const APPROVED_ANATOMICAL_MEDIA={...FILE_EXERCISE_MEDIA,...(window.GYM_EXERCISE_IMAGES||{})};
function handleExerciseImageError(img){
  const fallback=img?.dataset?.fallback||'';
  if(fallback&&!img.dataset.fallbackUsed){img.dataset.fallbackUsed='1';img.src=fallback;return;}
  const box=img?.closest?.('.exercise-media');
  if(box)box.innerHTML='<span class="image-unavailable">Imagem indisponível</span>';
}
function exerciseMedia(id,e,extraClass=''){
  const src=APPROVED_ANATOMICAL_MEDIA[id];
  if(!src||!e)return '';
  const fallback=FILE_EXERCISE_MEDIA[id]||'';
  return `<div class="exercise-media anatomical-media ${extraClass}"><img src="${src}" data-fallback="${fallback}" alt="Ilustração anatômica de ${e.name}, com a musculatura trabalhada destacada" loading="lazy" decoding="async" onerror="handleExerciseImageError(this)"></div>`;
}
