const FOCUS_OPTIONS={
 balanced:{name:'Corpo todo equilibrado',desc:'Distribuição uniforme entre os principais grupos musculares.'},
 legs:{name:'Pernas e quadríceps',desc:'Mais variedade e volume para a parte anterior das pernas.'},
 glutes:{name:'Glúteos e posteriores',desc:'Ênfase em glúteos e parte posterior das coxas.'},
 back:{name:'Costas',desc:'Mais puxadas e remadas ao longo da semana.'},
 chest:{name:'Peito',desc:'Maior presença de supinos e movimentos para peitoral.'},
 shoulders:{name:'Ombros',desc:'Inclui desenvolvimento e elevações em dias específicos.'},
 arms:{name:'Braços',desc:'Mais estímulos diretos para bíceps e tríceps.'},
 core:{name:'Abdômen e core',desc:'Mais exercícios para estabilidade e controle do tronco.'}
};
const FOCUS_EXTRAS={
 machines:{
  legs:['pendulum_squat','belt_squat','single_leg_press','leg_extension_unilateral','hack_squat','smith_lunge'],
  glutes:['glute','cable_kickback','abductor','adductor_machine','hip','cable_pullthrough'],
  back:['pulldown_neutral','pulldown_unilateral','high_row_machine','reverse_pecdeck','face_pull_cable','row_machine'],
  chest:['incline_chest_machine','smith_bench_press','smith_incline_press','pecdeck','cable_fly_low_high','cable_fly_high_low'],
  shoulders:['lateral_cable','rear_delt_cable','face_pull_cable','shoulder','lateral','front_raise_cable'],
  arms:['armcurl_machine','cable_curl_bar','cable_curl_rope','triceps_bar','pushdown_single_arm','pushdown_reverse_grip'],
  core:['cable_crunch','pallof_press','woodchop_high_low','captain_knee_raise','side_plank','reverse_crunch']
 },
 mixed:{
  legs:['front_squat_barbell','bulgarian_split_squat_db','walking_lunge_db','landmine_squat','step_up_db','rdl_dumbbell'],
  glutes:['single_leg_rdl_db','glute_bridge_barbell','hip_thrust_dumbbell','cable_pullthrough','frog_pump','deadlift_sumo'],
  back:['barbell_row','tbar_row','chest_supported_db_row','pullup_pronated','dumbbell_pullover','landmine_row'],
  chest:['bench_press_barbell','bench_press_dumbbell','incline_press_dumbbell','chest_dip','fly_dumbbell_flat','floor_press_dumbbell'],
  shoulders:['military_press_barbell_seated','arnold_press','lateral_raise_db','rear_delt_fly_db','landmine_press_unilateral','y_raise_incline'],
  arms:['curl_alternating_db','spider_curl_db','hammer_curl_crossbody','skullcrusher_ez','close_grip_bench_press','triceps_kickback_db'],
  core:['pallof_press','hanging_knee_raise','ab_wheel','dead_bug','russian_twist','farmer_carry']
 }
};
function normalizedFocusAreas(value){const raw=Array.isArray(value)?value.filter(x=>FOCUS_OPTIONS[x]):[];if(!raw.length||raw.includes('balanced'))return ['balanced'];return [...new Set(raw)].slice(0,3)}
function focusNames(value){return normalizedFocusAreas(value).map(x=>FOCUS_OPTIONS[x]?.name).filter(Boolean).join(', ')}
function toggleFocusList(list,id){let current=normalizedFocusAreas(list);if(id==='balanced')return ['balanced'];current=current.filter(x=>x!=='balanced');if(current.includes(id))current=current.filter(x=>x!==id);else if(current.length<3)current.push(id);else{toast('Escolha no máximo 3 áreas de foco.');return current}return current.length?current:['balanced']}
function dayFocusScore(day,focus){const hints={legs:['quadríceps','pernas'],glutes:['glúteos','posteriores'],back:['costas'],chest:['peito'],shoulders:['ombros'],arms:['bíceps','tríceps','braços'],core:['core','abdômen']},name=String(day.name||'').toLocaleLowerCase('pt-BR'),nameBonus=(hints[focus]||[]).some(x=>name.includes(x))?6:0;return nameBonus+(day.ids||[]).reduce((n,id)=>n+((EX_GROUPS[id]||[]).includes(focus)?1:0),0)}
function adaptExerciseForPreference(id,preference,index){if(preference!=='mixed')return id;const alternatives={legpressh:'front_squat_barbell',legpress:'dumbbell_squat',extension:'bulgarian_split_squat_db',curl:'rdl_dumbbell',hip:'hip_thrust_barbell',abductor:'hip_abduction_band',row_machine:'barbell_row',row:'chest_supported_db_row',pulldown:'pullup_pronated',pulldown_close:'chinup_supinated',chest:'bench_press_barbell',incline_chest_machine:'incline_press_dumbbell',pecdeck:'fly_dumbbell_flat',shoulder:'military_press_barbell_seated',lateral:'lateral_raise_db',armcurl:'curl_alternating_db',triceps:'skullcrusher_ez',calf:'single_leg_calf_raise'};return index%2===1&&alternatives[id]&&EX[alternatives[id]]?alternatives[id]:id}
function applyFocusEmphasis(tpl,p){const focuses=normalizedFocusAreas(p.focusAreas).filter(x=>x!=='balanced'),capacity=(+p.duration||60)<=40?6:(+p.duration||60)<=50?7:(+p.duration||60)<=60?8:9;if(!focuses.length)return tpl;for(const focus of focuses){const ranked=tpl.map((day,i)=>({day,i,score:dayFocusScore(day,focus)})).sort((a,b)=>b.score-a.score||a.i-b.i);const target=ranked[0]?.day;if(!target)continue;const pool=FOCUS_EXTRAS[p.preference==='mixed'?'mixed':'machines'][focus]||[];const extra=pool.find(id=>EX[id]&&!target.ids.includes(id));if(!extra)continue;if(target.ids.length>=capacity){let remove=-1;for(let i=target.ids.length-1;i>=0;i--){const groups=EX_GROUPS[target.ids[i]]||[];if(!groups.includes(focus)&&!['legpressh','chest','pulldown','row_machine','curl','hip'].includes(target.ids[i])){remove=i;break}}if(remove>=0)target.ids.splice(remove,1,extra)}else target.ids.push(extra);target.focusAreas=[...(target.focusAreas||[]),focus]}
 return tpl}


function blankState(){const now=new Date().toISOString();return {profile:null,plan:null,sessions:[],metrics:[],pain:[],recoveryCheckins:[],active:null,settings:{theme:'dark'},meta:{createdAt:now,updatedAt:now,version:'5.12.0'}}}
let state=blankState();
function localKey(){return 'emyfit_pro_state_'+(currentUser?.id||'demo')}
function loadLocal(){try{state={...blankState(),...JSON.parse(localStorage.getItem(localKey())||'{}')}}catch{state=blankState()}normalizeState()}
function touchState(){state.meta={...(state.meta||{}),createdAt:state.meta?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),version:'5.12.0'}}
function saveLocal(scheduleCloud=true){touchState();try{localStorage.setItem(localKey(),JSON.stringify(state))}catch(err){console.warn('Falha ao salvar localmente',err)}if(scheduleCloud)scheduleCloudSave()}
let saveTimer=null,cloudWriteChain=Promise.resolve();function scheduleCloudSave(){if(!cloud||!currentUser)return;clearTimeout(saveTimer);saveTimer=setTimeout(syncUp,300)}
function syncUp(){if(!cloud||!currentUser)return Promise.resolve(false);const snapshot=JSON.parse(JSON.stringify(state));cloudWriteChain=cloudWriteChain.catch(()=>false).then(async()=>{const {error}=await cloud.from('user_app_state').upsert({user_id:currentUser.id,data:snapshot,updated_at:new Date().toISOString()});if(error){console.warn(error);return false}return true});return cloudWriteChain}
function stateTime(x){const t=Date.parse(x?.meta?.updatedAt||x?.meta?.createdAt||'');return Number.isFinite(t)?t:0}
function activeProgress(x){if(!x?.active)return -1;let n=0;(x.active.exercises||[]).forEach(e=>(e.sets||[]).forEach(a=>{if(a.done)n+=10;if(a.kg!==''&&a.kg!=null)n+=1;if(a.reps!==''&&a.reps!=null)n+=1;if(a.rir!==''&&a.rir!=null)n+=1}));return n}
async function syncDown(){if(!cloud||!currentUser)return false;let local=null;try{local=JSON.parse(localStorage.getItem(localKey())||'null')}catch{}const {data,error}=await cloud.from('user_app_state').select('data,updated_at').eq('user_id',currentUser.id).maybeSingle();if(error){console.warn(error);return false}const remote=data?.data||null;if(remote){const lp=activeProgress(local),rp=activeProgress(remote),lt=stateTime(local),rt=stateTime(remote)||(Date.parse(data.updated_at||'')||0);const localWins=local&&((local.active&&remote.active)?(lp>rp||(lp===rp&&lt>rt)):lt>rt);if(localWins){state={...blankState(),...local};normalizeState();localStorage.setItem(localKey(),JSON.stringify(state));await syncUp();return true}state={...blankState(),...remote};normalizeState();localStorage.setItem(localKey(),JSON.stringify(state));return true}if(local){state={...blankState(),...local};normalizeState();await syncUp();return true}return false}


function normalizeState(){
 const all=Object.keys(CARDIO);
 state.meta={...(state.meta||{}),createdAt:state.meta?.createdAt||new Date().toISOString(),updatedAt:state.meta?.updatedAt||state.meta?.createdAt||'',version:'5.12.0'};
 if(!Array.isArray(state.recoveryCheckins))state.recoveryCheckins=[];
 if(!Array.isArray(state.sessions))state.sessions=[];
 if(!Array.isArray(state.metrics))state.metrics=[];
 if(!Array.isArray(state.pain))state.pain=[];
 if(state.profile)state.profile.focusAreas=normalizedFocusAreas(state.profile.focusAreas);
 if(state.plan?.days)state.plan.days.forEach(d=>{if(!CARDIO[d.cardioType])d.cardioType='bike_h';d.cardioOptions=all.slice()});
 if(state.active){
  const validActiveDay=Array.isArray(state.plan?.days)&&state.plan.days.some(d=>d.id===state.active.dayId);
  if(!validActiveDay){state.active=null;saveLocal(false);return;}
  if(!CARDIO[state.active.cardioType])state.active.cardioType='bike_h';
  state.active.cardioOptions=all.slice();
  state.active.finishDraft={cardio:state.active.cardio||0,cardioType:state.active.cardioType||'bike_h',speed:'',incline:'',level:'',distance:'',pace:'',floors:'',pain:0,rpe:7,notes:'',...(state.active.finishDraft||{})}
 }
}

function saveFinishField(k,v){if(!state.active)return;state.active.finishDraft=state.active.finishDraft||{};state.active.finishDraft[k]=v;saveLocal()}
function chooseFinishCardio(id){if(!state.active||!CARDIO[id])return;state.active.cardioType=id;state.active.finishDraft=state.active.finishDraft||{};state.active.finishDraft.cardioType=id;saveLocal();renderCardioFields()}
function persistActiveFromDOM(scheduleCloud=true){if(!state.active)return;const q=id=>document.getElementById(id);state.active.finishDraft=state.active.finishDraft||{};const map={finishCardio:'cardio',finishCardioType:'cardioType',cardioSpeed:'speed',cardioIncline:'incline',cardioLevel:'level',cardioDistance:'distance',cardioPace:'pace',cardioFloors:'floors',finishPain:'pain',finishRpe:'rpe',finishNotes:'notes'};Object.entries(map).forEach(([id,key])=>{const el=q(id);if(el)state.active.finishDraft[key]=el.value});if(state.active.finishDraft.cardioType&&CARDIO[state.active.finishDraft.cardioType])state.active.cardioType=state.active.finishDraft.cardioType;saveLocal(scheduleCloud)}
function flushActiveWorkout(){if(!state.active)return;persistActiveFromDOM(false);try{localStorage.setItem(localKey(),JSON.stringify(state))}catch{}clearTimeout(saveTimer);syncUp()}
let persistenceGuardsInstalled=false;
function installPersistenceGuards(){if(persistenceGuardsInstalled)return;persistenceGuardsInstalled=true;document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flushActiveWorkout()});window.addEventListener('pagehide',flushActiveWorkout);window.addEventListener('beforeunload',flushActiveWorkout);window.addEventListener('freeze',flushActiveWorkout)}

function initCloud(){if(C.supabaseUrl&&C.supabaseAnonKey&&window.supabase){cloud=window.supabase.createClient(C.supabaseUrl,C.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});return true}return false}
function toast(m){const t=$('#toast');if(!t)return; t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}
function modal(html){document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="modal"><div class="modal-card"><button class="modal-close" onclick="closeModal()">×</button>${html}</div></div>`)}
function closeModal(){$('#modal')?.remove()}
function setScreen(s){screen=s;renderApp();scrollTo(0,0)}
function setAuthMessage(message='',type='notice'){authMessage=message;authMessageType=type;const box=document.getElementById('authStatus');if(!box)return;box.className=type;box.textContent=message;box.hidden=!message}
function setAuthBusy(busy,label='Entrando…'){authBusy=busy;const btn=document.getElementById('authSubmit');if(btn){btn.disabled=busy;btn.textContent=busy?label:(authMode==='login'?'Entrar':'Criar minha conta')}}
function friendlyAuthError(error){const raw=String(error?.message||error||'').toLowerCase();if(raw.includes('invalid login credentials'))return 'E-mail ou senha incorretos.';if(raw.includes('email not confirmed'))return 'Confirme o e-mail da conta antes de entrar.';if(raw.includes('too many requests')||raw.includes('rate limit'))return 'Muitas tentativas. Aguarde alguns minutos e tente novamente.';if(raw.includes('failed to fetch')||raw.includes('network')||raw.includes('load failed'))return 'Não foi possível conectar à nuvem. Verifique a internet e tente novamente.';return error?.message||'Não foi possível entrar. Tente novamente.'}
function withTimeout(promise,ms){return Promise.race([promise,new Promise((_,reject)=>setTimeout(()=>reject(new Error('Tempo limite de conexão excedido.')),ms))])}
async function hydrateSession(session){currentUser=session?.user||null;if(currentUser){loadLocal();await syncDown();}else screen='home';renderRoot()}
function scheduleAuthHydration(session){clearTimeout(authHydrationTimer);authHydrationTimer=setTimeout(()=>{hydrateSession(session).catch(err=>{console.warn('Falha ao atualizar sessão',err);renderRoot()})},0)}

async function boot(){installPersistenceGuards();const has=initCloud();if(has){try{const {data,error}=await cloud.auth.getSession();if(error)console.warn(error);currentUser=data?.session?.user||null;if(currentUser){loadLocal();await syncDown()}}catch(err){console.warn('Falha ao restaurar sessão',err)}cloud.auth.onAuthStateChange((event,session)=>{currentUser=session?.user||null;if(event==='SIGNED_IN'&&authBusy)return;if(event==='TOKEN_REFRESHED')return;scheduleAuthHydration(session)})}renderRoot();if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js', {scope:'./', updateViaCache:'none'}).then(reg=>reg.update()).catch(()=>{})}
function renderRoot(){if(!currentUser&&!localStorage.getItem('emyfit_demo'))renderAuth();else{loadLocal();if(!state.profile?.onboardingComplete)renderOnboarding();else{if(state.active)screen='workout';renderApp()}}}

function renderAuth(){
 $('#app').innerHTML=`<div class="auth-page"><div class="auth-card"><div class="auth-logo premium-logo">${brandMark()}</div><div class="premium-tag">♛ PREMIUM</div><button class="btn primary block install-app-btn" style="margin:12px 0" onclick="installApp()">Instalar o app GYM</button><span class="eyebrow">GYM</span><h1 style="margin:7px 0">Seu treino. Sua evolução. Seu melhor.</h1><p class="muted">Conta, avaliação inteligente, treino adaptativo, recuperação muscular, cardio e relatórios premium.</p>
 <div class="auth-tabs"><button class="${authMode==='login'?'active':''}" onclick="authMode='login';authMessage='';renderAuth()">Entrar</button><button class="${authMode==='signup'?'active':''}" onclick="authMode='signup';authMessage='';renderAuth()">Criar conta</button></div>
 ${!cloud?`<div class="notice"><b>Nuvem ainda não configurada.</b><br>O pacote inclui o banco e o login, mas você precisa conectar seu projeto Supabase. Enquanto isso, use o modo de demonstração local.</div>`:''}
 <form onsubmit="submitAuth(event)"><label>E-mail</label><input id="authEmail" type="email" inputmode="email" autocomplete="email" required placeholder="voce@email.com"><label>Senha</label><input id="authPass" type="password" autocomplete="${authMode==='login'?'current-password':'new-password'}" required placeholder="${authMode==='login'?'Digite sua senha':'mínimo de 8 caracteres'}">
 <div id="authStatus" class="${authMessageType}" ${authMessage?'':'hidden'} style="margin-top:12px">${authMessage}</div>
 <button id="authSubmit" type="submit" class="btn primary block" style="margin-top:15px" ${authBusy?'disabled':''}>${authBusy?(authMode==='login'?'Entrando…':'Criando conta…'):(authMode==='login'?'Entrar':'Criar minha conta')}</button></form>
 ${authMode==='login'?`<button class="btn ghost block" style="margin-top:9px" onclick="forgotPassword()">Esqueci minha senha</button>`:''}
 ${!cloud?`<button class="btn secondary block" style="margin-top:9px" onclick="startDemo()">Entrar em modo demonstração</button>`:''}
 <p class="small muted" style="margin-top:16px">Os dados de saúde e treino só devem ser usados para personalização e não substituem avaliação profissional.</p></div></div>`
}
async function submitAuth(event){event?.preventDefault();if(authBusy)return;if(!cloud){setAuthMessage('A nuvem não está configurada neste arquivo.','dangerbox');return}const email=$('#authEmail')?.value.trim(),password=$('#authPass')?.value||'';if(!email){setAuthMessage('Informe o e-mail.','dangerbox');return}if(!password){setAuthMessage('Informe a senha.','dangerbox');return}if(authMode==='signup'&&password.length<8){setAuthMessage('Para criar uma conta, use uma senha com pelo menos 8 caracteres.','dangerbox');return}setAuthMessage(authMode==='login'?'Validando sua conta…':'Criando sua conta…','notice');setAuthBusy(true,authMode==='login'?'Entrando…':'Criando conta…');try{const result=await withTimeout(authMode==='login'?cloud.auth.signInWithPassword({email,password}):cloud.auth.signUp({email,password}),20000);if(result.error){setAuthMessage(friendlyAuthError(result.error),'dangerbox');return}if(authMode==='signup'&&!result.data.session){setAuthMessage('Conta criada. Confira seu e-mail para confirmar o cadastro.','success');return}clearTimeout(authHydrationTimer);currentUser=result.data.session?.user||result.data.user||null;if(!currentUser){setAuthMessage('A conta foi validada, mas a sessão não foi criada. Tente entrar novamente.','dangerbox');return}loadLocal();setAuthMessage('Conta validada. Carregando seus dados…','success');try{await withTimeout(syncDown(),15000)}catch(syncError){console.warn('Login concluído, mas a sincronização demorou',syncError)}screen='home';authMessage='';renderRoot()}catch(error){console.warn('Falha de autenticação',error);setAuthMessage(friendlyAuthError(error),'dangerbox')}finally{setAuthBusy(false)}}
async function forgotPassword(){if(!cloud){setAuthMessage('A nuvem não está configurada.','dangerbox');return}const email=$('#authEmail')?.value.trim();if(!email){setAuthMessage('Informe o e-mail para receber o link.','dangerbox');return}try{const {error}=await withTimeout(cloud.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname}),20000);setAuthMessage(error?friendlyAuthError(error):'Link de recuperação enviado para o e-mail informado.',error?'dangerbox':'success')}catch(error){setAuthMessage(friendlyAuthError(error),'dangerbox')}}
function startDemo(){localStorage.setItem('emyfit_demo','1');currentUser=null;loadLocal();renderRoot()}

const wizard={basic:{},goal:'fatloss',focusAreas:['balanced'],days:4,duration:60,experience:'beginner',preference:'machines',cardio:'bike_h',limitations:[],screening:[],sleep:'7',stress:'medium'};
function renderOnboarding(){const steps=[stepWelcome,stepBasic,stepGoal,stepFocus,stepRoutine,stepLimits,stepReview];$('#app').innerHTML=`<div class="auth-page"><div class="auth-card" style="width:min(620px,100%)"><div class="stepper">${steps.map((_,i)=>`<span class="${i<=wizardStep?'done':''}"></span>`).join('')}</div>${steps[wizardStep]()}</div></div>`}
function navWizard(n){wizardStep=clamp(wizardStep+n,0,6);renderOnboarding()}
function stepWelcome(){return `<span class="eyebrow">AVALIAÇÃO INICIAL</span><h1>Primeiro entendemos você.</h1><p class="muted">O treino será criado considerando objetivo, áreas de foco, rotina, experiência, preferência por aparelhos e limitações informadas.</p><div class="source"><b>O que a IA não faz</b><p>Não diagnostica lesões, não substitui professor e não libera exercício diante de sinais de alerta.</p></div><button class="btn primary block" onclick="navWizard(1)">Começar avaliação ${icon('arrow')}</button>`}
function maskBirthDateInput(el){let v=String(el.value||'').replace(/\D/g,'').slice(0,8);if(v.length>4)v=v.slice(0,2)+'/'+v.slice(2,4)+'/'+v.slice(4);else if(v.length>2)v=v.slice(0,2)+'/'+v.slice(2);el.value=v}
function birthForInput(value){const v=String(value||'');const m=v.match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?`${m[3]}/${m[2]}/${m[1]}`:v}
function parseBirthInput(value){const m=String(value||'').match(/^(\d{2})\/(\d{2})\/(\d{4})$/);if(!m)return null;const day=+m[1],month=+m[2],year=+m[3],d=new Date(year,month-1,day);if(d.getFullYear()!==year||d.getMonth()!==month-1||d.getDate()!==day)return null;const now=new Date(),age=now.getFullYear()-year-((now.getMonth()<month-1||(now.getMonth()===month-1&&now.getDate()<day))?1:0);if(age<13||age>100)return null;return `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`}
function stepBasic(){return `<span class="eyebrow">DADOS BÁSICOS</span><h2>Conte sobre você</h2><div class="grid grid2"><div><label>Nome</label><input id="wName" value="${wizard.basic.name||''}"></div><div><label>Data de nascimento</label><input id="wBirth" type="text" inputmode="numeric" maxlength="10" placeholder="DD/MM/AAAA" value="${birthForInput(wizard.basic.birth||'')}" oninput="maskBirthDateInput(this)"></div><div><label>Altura (cm)</label><input id="wHeight" type="number" value="${wizard.basic.height||''}"></div><div><label>Peso atual (kg)</label><input id="wWeight" type="number" step=".1" value="${wizard.basic.weight||''}"></div></div><label>Como prefere ser tratada(o)?</label><select id="wGender"><option value="not" ${wizard.basic.gender==='not'?'selected':''}>Prefiro não informar</option><option value="female" ${wizard.basic.gender==='female'?'selected':''}>Feminino</option><option value="male" ${wizard.basic.gender==='male'?'selected':''}>Masculino</option><option value="other" ${wizard.basic.gender==='other'?'selected':''}>Outro</option></select><div class="row between" style="margin-top:18px"><button class="btn ghost" onclick="navWizard(-1)">Voltar</button><button class="btn primary" onclick="saveBasic()">Continuar</button></div>`}
function saveBasic(){const birth=parseBirthInput($('#wBirth').value);wizard.basic={name:$('#wName').value.trim(),birth,height:+$('#wHeight').value,weight:+$('#wWeight').value,gender:$('#wGender').value};if(!wizard.basic.name||!wizard.basic.height||!wizard.basic.weight)return toast('Preencha nome, altura e peso.');if(!birth)return toast('Digite uma data válida no formato DD/MM/AAAA.');navWizard(1)}
function selectOne(key,val){wizard[key]=val;renderOnboarding()}
function stepGoal(){const opts=[['fatloss','Emagrecimento','Reduzir gordura preservando força e massa magra.'],['definition','Definição','Melhorar composição corporal e aparência muscular.'],['strength','Força','Aumentar desempenho nos exercícios.'],['health','Saúde e disposição','Criar consistência e condicionamento geral.']];return `<span class="eyebrow">OBJETIVO</span><h2>Qual é a prioridade?</h2><div class="choice-grid">${opts.map(o=>`<button class="choice ${wizard.goal===o[0]?'selected':''}" onclick="selectOne('goal','${o[0]}')"><b>${o[1]}</b><span class="muted small">${o[2]}</span></button>`).join('')}</div><div class="row between" style="margin-top:18px"><button class="btn ghost" onclick="navWizard(-1)">Voltar</button><button class="btn primary" onclick="navWizard(1)">Continuar</button></div>`}
function toggleWizardFocus(id){wizard.focusAreas=toggleFocusList(wizard.focusAreas,id);renderOnboarding()}
function stepFocus(){return `<span class="eyebrow">FOCO DO TREINO</span><h2>Quais áreas você quer priorizar?</h2><p class="muted small">Escolha até 3 áreas. O plano continua equilibrado, mas essas regiões recebem mais variedade e volume.</p><div class="choice-grid">${Object.entries(FOCUS_OPTIONS).map(([id,o])=>`<button class="choice ${normalizedFocusAreas(wizard.focusAreas).includes(id)?'selected':''}" onclick="toggleWizardFocus('${id}')"><b>${o.name}</b><span class="muted small">${o.desc}</span></button>`).join('')}</div><div class="row between" style="margin-top:18px"><button class="btn ghost" onclick="navWizard(-1)">Voltar</button><button class="btn primary" onclick="navWizard(1)">Continuar</button></div>`}
function stepRoutine(){return `<span class="eyebrow">ROTINA</span><h2>Um plano que cabe na vida real</h2><label>Dias disponíveis por semana</label><div class="choice-grid">${[2,3,4,5].map(n=>`<button class="choice ${wizard.days===n?'selected':''}" onclick="selectOne('days',${n})"><b>${n} dias</b><span class="muted small">${n<=3?'Mais recuperação':'Maior distribuição de volume'}</span></button>`).join('')}</div><label>Duração máxima</label><select id="wDuration" onchange="wizard.duration=+this.value"><option value="40" ${wizard.duration===40?'selected':''}>40 minutos</option><option value="50" ${wizard.duration===50?'selected':''}>50 minutos</option><option value="60" ${wizard.duration===60?'selected':''}>60 minutos</option><option value="75" ${wizard.duration===75?'selected':''}>75 minutos</option></select><label>Experiência</label><select id="wExperience" onchange="wizard.experience=this.value"><option value="beginner" ${wizard.experience==='beginner'?'selected':''}>Iniciante / retornando</option><option value="intermediate" ${wizard.experience==='intermediate'?'selected':''}>Intermediário</option><option value="advanced" ${wizard.experience==='advanced'?'selected':''}>Avançado</option></select><label>Preferência</label><select id="wPreference" onchange="wizard.preference=this.value"><option value="machines" ${wizard.preference==='machines'?'selected':''}>Principalmente aparelhos</option><option value="mixed" ${wizard.preference==='mixed'?'selected':''}>Misto</option></select><label>Cardio preferido</label><div class="choice-grid">${Object.entries(CARDIO).map(([k,v])=>`<button class="choice ${wizard.cardio===k?'selected':''}" onclick="selectOne('cardio','${k}')"><b>${v.name}</b><span class="muted small">Impacto ${v.impact}</span></button>`).join('')}</div><div class="row between" style="margin-top:18px"><button class="btn ghost" onclick="navWizard(-1)">Voltar</button><button class="btn primary" onclick="navWizard(1)">Continuar</button></div>`}
function toggleArr(key,val){const a=wizard[key];const i=a.indexOf(val);i>=0?a.splice(i,1):a.push(val);renderOnboarding()}
function stepLimits(){const limits=[['knee','Dor ou limitação nos joelhos'],['back','Dor ou limitação lombar'],['shoulder','Dor ou limitação nos ombros'],['none','Nenhuma limitação relevante']];const red=[['chest','Dor no peito com esforço'],['faint','Desmaio ou tontura importante'],['medical','Restrição médica para exercício'],['acute','Lesão aguda ou cirurgia recente']];return `<span class="eyebrow">SEGURANÇA</span><h2>O que precisamos respeitar?</h2><p class="muted small">Marque tudo que se aplica. Isso não é diagnóstico nem substitui triagem profissional.</p><label>Limitações musculoesqueléticas</label><div class="choice-grid">${limits.map(o=>`<button class="choice ${wizard.limitations.includes(o[0])?'selected':''}" onclick="toggleArr('limitations','${o[0]}')"><b>${o[1]}</b></button>`).join('')}</div><label>Sinais que exigem avaliação antes de progredir</label><div class="choice-grid">${red.map(o=>`<button class="choice ${wizard.screening.includes(o[0])?'selected':''}" onclick="toggleArr('screening','${o[0]}')"><b>${o[1]}</b></button>`).join('')}</div><label>Sono médio</label><select onchange="wizard.sleep=this.value"><option value="lt6">Menos de 6h</option><option value="6">6–7h</option><option value="7" ${wizard.sleep==='7'?'selected':''}>7–8h</option><option value="8" ${wizard.sleep==='8'?'selected':''}>Mais de 8h</option></select><div class="row between" style="margin-top:18px"><button class="btn ghost" onclick="navWizard(-1)">Voltar</button><button class="btn primary" onclick="navWizard(1)">Revisar</button></div>`}
function stepReview(){const risk=wizard.screening.length>0;return `<span class="eyebrow">PLANO PERSONALIZADO</span><h2>Pronto para gerar</h2><div class="grid grid2"><div class="metric"><b>${wizard.days}×</b><span>por semana</span></div><div class="metric"><b>${wizard.duration} min</b><span>por sessão</span></div></div><div class="card flat"><h3>${wizard.basic.name}</h3><p class="muted small">Objetivo: ${goalName(wizard.goal)}<br>Foco: ${focusNames(wizard.focusAreas)}<br>Preferência: ${wizard.preference==='machines'?'aparelhos':'misto'}<br>Cardio preferido: ${cardioName(wizard.cardio)}<br>Limitações: ${wizard.limitations.length?wizard.limitations.join(', '):'nenhuma informada'}</p></div>${risk?`<div class="dangerbox"><b>Atenção:</b> você marcou um sinal que pede avaliação profissional antes de aumentar a atividade. O app criará um plano conservador, mas não equivale a liberação médica.</div>`:`<div class="success">Nenhum sinal de alerta foi marcado. Ainda assim, dor nova ou sintomas importantes exigem interrupção e avaliação.</div>`}<button class="btn primary block" style="margin-top:14px" onclick="finishOnboarding()">Gerar meu plano</button><button class="btn ghost block" style="margin-top:8px" onclick="navWizard(-1)">Voltar</button>`}
function goalName(x){return ({fatloss:'Emagrecimento',definition:'Definição',strength:'Força',health:'Saúde e disposição'})[x]||'Objetivo personalizado'}
function generatePlan(p){let days=clamp(+p.days||3,2,5),tpl=JSON.parse(JSON.stringify(templates[days]));const limitations=Array.isArray(p.limitations)?p.limitations:[],screening=Array.isArray(p.screening)?p.screening:[],focusAreas=normalizedFocusAreas(p.focusAreas),knee=limitations.includes('knee'),back=limitations.includes('back'),risk=screening.length>0;tpl=applyFocusEmphasis(tpl,{...p,focusAreas});tpl.forEach((w,dayIndex)=>{w.id=uid();const seen=new Set();w.exercises=w.ids.map((rawId,index)=>adaptExerciseForPreference(rawId,p.preference,index+dayIndex)).map(id=>{if(knee&&id==='legpress')id='legpressh';if(back&&id==='curllying')id='curl';return id}).filter(id=>EX[id]&&!seen.has(id)&&seen.add(id)).map(id=>{const e=EX[id];let sets=e.sets;const emphasized=focusAreas.some(f=>f!=='balanced'&&(EX_GROUPS[id]||[]).includes(f));if(emphasized)sets=Math.min(4,sets+1);if(p.experience==='beginner'||risk)sets=Math.max(2,sets-1);return {id,sets,reps:e.reps,rest:e.rest,reason:emphasized?`Ênfase escolhida: ${e.why}`:e.why};});delete w.ids;w.cardio=p.goal==='fatloss'?Math.min(25,10+days*2):12;w.cardioType=p.cardio||'bike_h';w.cardioOptions=[p.cardio||'bike_h','treadmill','elliptical','bike_h','bike_v'].filter((v,i,a)=>a.indexOf(v)===i);});const focusTitle=focusAreas.includes('balanced')?'Equilibrado':focusAreas.map(x=>FOCUS_OPTIONS[x].name).join(' + ');return {id:uid(),name:`Plano ${days}x — ${goalName(p.goal)} · ${focusTitle}`,createdAt:today(),cycleWeeks:6,focusAreas,days:tpl,basis:['acsm','who','obesity',...(knee?['knee']:[])],status:'active'}}
function finishOnboarding(){state.profile={...wizard.basic,goal:wizard.goal,focusAreas:normalizedFocusAreas(wizard.focusAreas),days:wizard.days,duration:wizard.duration,experience:wizard.experience,preference:wizard.preference,limitations:wizard.limitations,screening:wizard.screening,sleep:wizard.sleep,onboardingComplete:true};state.plan=generatePlan({...state.profile});state.metrics.push({date:today(),weight:state.profile.weight});saveLocal();screen='home';renderApp();toast('Seu plano personalizado foi criado.')}


function shell(content){return `<div class="app-shell"><header class="topbar"><div class="brand"><div class="logo premium-logo-small">${brandMark()}</div><div><b>GYM</b><small>PREMIUM • PLANO ADAPTATIVO</small></div></div><div class="row"><button class="install-mini install-app-btn" onclick="installApp()">Instalar</button><div class="avatar">${(state.profile?.name||'E').slice(0,1).toUpperCase()}</div></div></header><main class="main">${content}</main><nav class="bottomnav">${[['home','home','Início'],['workout','workout','Treino'],['coach','coach','Coach'],['reports','chart','Relatórios'],['profile','user','Perfil']].map(x=>`<button class="${screen===x[0]?'active':''}" onclick="setScreen('${x[0]}')">${icon(x[1])}${x[2]}</button>`).join('')}</nav></div>`}
function renderApp(){const fn={home:homeScreen,workout:workoutScreen,coach:coachScreen,reports:reportsScreen,profile:profileScreen}[screen]||homeScreen;$('#app').innerHTML=shell(fn())}
function weekSessions(){let d=new Date();d.setDate(d.getDate()-6);return state.sessions.filter(s=>new Date(s.date)>=d)}
function nextDay(){return state.plan.days[state.sessions.length%state.plan.days.length]}
function homeScreen(){
 const wk=weekSessions(),next=nextDay(),metrics=Array.isArray(state.metrics)?state.metrics:[],lastMetric=metrics.length?metrics[metrics.length-1]:null,lastW=lastMetric?.weight||state.profile?.weight||'—',days=Math.max(1,+state.profile?.days||1),adherence=Math.round(wk.length/days*100),readiness=overallRecoveryScore(),planDays=Array.isArray(state.plan?.days)?state.plan.days:[];
 return `<section class="hero"><span class="eyebrow">BOM TREINO, ${(state.profile?.name||'ATLETA').toUpperCase()}</span><h1>${next?.name||'Seu próximo treino'}</h1><p>${next?.exercises?.length||0} exercícios · treino personalizado para hoje</p>${next?.id?`<button class="btn primary" style="margin-top:18px" onclick="startWorkout('${next.id}')">${icon('play')} Iniciar treino</button>`:''}</section><div class="grid grid3" style="margin-top:12px"><div class="metric"><b>${wk.length}/${days}</b><span>treinos esta semana</span></div><div class="metric"><b>${lastW} kg</b><span>peso registrado</span></div><div class="metric"><b>${readiness}%</b><span>prontidão geral</span></div></div><div class="card"><div class="row between"><div><h3>Aderência semanal</h3><span class="muted small">Consistência antes de complexidade.</span></div><b>${clamp(adherence,0,100)}%</b></div><div class="progress" style="margin-top:13px"><span style="width:${clamp(adherence,0,100)}%"></span></div></div><div class="card premium-recovery"><div class="row between"><div><span class="eyebrow">FADIGA MUSCULAR</span><h3 style="margin-top:6px">Prontidão para treinar</h3><p class="muted small">Estimativa por grupo muscular baseada no tempo desde o treino, séries concluídas, esforço geral e RIR.</p></div><div class="recovery-ring" style="--score:${readiness*3.6}deg"><div><b>${readiness}%</b><span>${overallRecoveryLabel()}</span></div></div></div>${recoveryCheckinSummary()}<button class="btn secondary block" style="margin:10px 0 12px" onclick="recoveryCheckinModal()">Atualizar como estou hoje</button>${recoveryBlock(6,false)}</div><div class="section-title"><h3>Seu plano</h3><span>Ciclo de ${state.plan?.cycleWeeks||'—'} semanas</span></div>${planDays.map((d,i)=>`<div class="card flat"><div class="row between"><div><span class="eyebrow">DIA ${i+1}</span><h3>${d.name}</h3><span class="muted small">${(d.exercises||[]).map(x=>EX[x.id]?.name||'Exercício').slice(0,3).join(' · ')}${(d.exercises||[]).length>3?'…':''}</span></div><button class="btn secondary sm" onclick="viewPlanDay('${d.id}')">Ver ${icon('arrow')}</button></div></div>`).join('')}<div class="card"><h3>Decisão rápida</h3><p class="muted small">Aparelho ocupado? O Coach compara padrão de movimento, musculatura, limitações e histórico antes de sugerir alternativas.</p><button class="btn ghost block" onclick="setScreen('coach')">${icon('coach')} Abrir Coach</button></div>`;
}
function sortedExercises(){return Object.entries(EX).sort((a,b)=>a[1].name.localeCompare(b[1].name,'pt-BR'))}
function exerciseCategoryOptions(){return Object.entries(EX_CATEGORY_LABELS).map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}
function exerciseWarning(e){const l=state.profile?.limitations||[];if((l.includes('knee')&&e.knee==='avoid')||(l.includes('back')&&e.back==='avoid')||(l.includes('shoulder')&&e.shoulder==='avoid'))return '<span class="pill bad">não indicado para sua limitação</span>';if(e.level==='avançado')return '<span class="pill warn">avançado</span>';return ''}
function pickerAction(mode,target,id){if(mode==='plan')return `addExerciseToPlan('${target}','${id}')`;if(mode==='replace')return `replaceExerciseManual(${target},'${id}')`;return `addExerciseToActive('${id}')`}
function renderExercisePicker(mode,target){const q=($('#exerciseSearch')?.value||'').trim().toLocaleLowerCase('pt-BR'),cat=$('#exerciseCategory')?.value||'all',box=$('#exercisePickerResults');if(!box)return;const list=sortedExercises().filter(([id,e])=>(cat==='all'||e.category===cat)&&(!q||`${e.name} ${e.machine} ${e.primary.join(' ')}`.toLocaleLowerCase('pt-BR').includes(q)));box.innerHTML=list.map(([id,e])=>`<div class="card flat" style="margin:8px 0"><div class="row between"><div style="min-width:0"><b>${e.name}</b><div class="muted small">${e.machine} · ${EX_CATEGORY_LABELS[e.category]||e.category}</div><div class="row wrap" style="margin-top:6px">${exerciseWarning(e)}</div></div><button class="btn primary sm" onclick="${pickerAction(mode,target,id)}">${mode==='replace'?'Trocar':'Adicionar'}</button></div></div>`).join('')||'<p class="muted">Nenhum exercício encontrado.</p>'}
function openPlanEditor(dayId){closeModal();const d=state.plan.days.find(x=>x.id===dayId);modal(`<span class="eyebrow">EDITAR TREINO</span><h2>${d.name}</h2><p class="muted small">Todas as opções ficam disponíveis em uma lista de texto. A imagem aparece somente quando o exercício entra no treino.</p><div id="planEditorCurrent"></div><hr><label>Buscar exercício</label><input id="exerciseSearch" placeholder="Digite o nome ou aparelho" oninput="renderExercisePicker('plan','${dayId}')"><label>Grupo</label><select id="exerciseCategory" onchange="renderExercisePicker('plan','${dayId}')">${exerciseCategoryOptions()}</select><div id="exercisePickerResults"></div><button class="btn primary block" style="margin-top:12px" onclick="closeModal();viewPlanDay('${dayId}')">Concluir edição</button>`);renderPlanEditor(dayId);renderExercisePicker('plan',dayId)}
function renderPlanEditor(dayId){const d=state.plan.days.find(x=>x.id===dayId),box=$('#planEditorCurrent');if(!box)return;box.innerHTML=`<h3>Exercícios do dia (${d.exercises.length})</h3>`+d.exercises.map((x,i)=>`<div class="row between" style="padding:10px 0;border-bottom:1px solid var(--line)"><div><b>${EX[x.id]?.name||x.id}</b><div class="muted small">${x.sets} séries · ${x.reps}</div></div><button class="btn danger sm" onclick="removeExerciseFromPlan('${dayId}',${i})">Remover</button></div>`).join('')}
function addExerciseToPlan(dayId,id){const d=state.plan.days.find(x=>x.id===dayId),e=EX[id];if(!d||!e)return;if(d.exercises.some(x=>x.id===id))return toast('Este exercício já está neste treino.');d.exercises.push({id,sets:e.sets,reps:e.reps,rest:e.rest,reason:e.why});saveLocal();renderPlanEditor(dayId);renderExercisePicker('plan',dayId);toast('Exercício adicionado ao plano.')}
function removeExerciseFromPlan(dayId,index){const d=state.plan.days.find(x=>x.id===dayId);if(!d)return;if(d.exercises.length<=1)return toast('O treino precisa manter pelo menos um exercício.');d.exercises.splice(index,1);saveLocal();renderPlanEditor(dayId);renderExercisePicker('plan',dayId)}
function openActiveExercisePicker(){closeModal();modal(`<span class="eyebrow">ADICIONAR AO TREINO</span><h2>Todas as opções</h2><p class="muted small">A lista não exibe fotos. A ilustração correspondente aparece no cartão depois que o exercício for adicionado.</p><label>Buscar exercício</label><input id="exerciseSearch" placeholder="Digite o nome ou aparelho" oninput="renderExercisePicker('active','')"><label>Grupo</label><select id="exerciseCategory" onchange="renderExercisePicker('active','')">${exerciseCategoryOptions()}</select><div id="exercisePickerResults"></div>`);renderExercisePicker('active','')}
function addExerciseToActive(id){const e=EX[id];if(!state.active||!e)return;if(state.active.exercises.some(x=>x.id===id))return toast('Este exercício já está no treino.');state.active.exercises.push({id,sets:Array.from({length:e.sets},()=>({kg:'',reps:'',rir:'',done:false}))});saveLocal();closeModal();renderApp();toast('Exercício adicionado ao treino atual.')}
function removeActiveExercise(index){if(!state.active||state.active.exercises.length<=1)return toast('O treino precisa manter pelo menos um exercício.');if(!confirm('Remover este exercício do treino em andamento?'))return;state.active.exercises.splice(index,1);saveLocal();renderApp()}
function openManualReplacement(index){closeModal();modal(`<span class="eyebrow">TROCAR EXERCÍCIO</span><h2>Escolha qualquer opção</h2><label>Buscar exercício</label><input id="exerciseSearch" placeholder="Digite o nome ou aparelho" oninput="renderExercisePicker('replace',${index})"><label>Grupo</label><select id="exerciseCategory" onchange="renderExercisePicker('replace',${index})">${exerciseCategoryOptions()}</select><div id="exercisePickerResults"></div>`);renderExercisePicker('replace',index)}
function replaceExerciseManual(index,id){const e=EX[id];if(!state.active||!e)return;state.active.exercises[index]={id,sets:Array.from({length:e.sets},()=>({kg:'',reps:'',rir:'',done:false}))};saveLocal();closeModal();renderApp();toast('Exercício trocado.')}

function latestRecoveryCheckin(){const a=state.recoveryCheckins||[];return a.length?a.slice().sort((x,y)=>(x.savedAt||x.date||'').localeCompare(y.savedAt||y.date||'')).at(-1):null}
function recoveryCheckinScore(){const c=latestRecoveryCheckin();if(!c)return null;return Math.round(((clamp(+c.sleep||3,1,5)+clamp(+c.energy||3,1,5)+(6-clamp(+c.soreness||3,1,5)))/15)*100)}
function recoveryCheckinSummary(){const c=latestRecoveryCheckin();if(!c)return `<div class="recovery-checkin empty"><b>Sem check-in de hoje</b><span>Registre sono, energia e cansaço muscular para complementar a estimativa automática.</span></div>`;const labels=['','muito baixo','baixo','regular','bom','ótimo'];const sore=['','nenhum','leve','moderado','alto','muito alto'];return `<div class="recovery-checkin"><div><b>Check-in de ${fmt(c.date)}</b><span>Sono ${labels[c.sleep]} · energia ${labels[c.energy]} · cansaço ${sore[c.soreness]}</span></div><strong>${recoveryCheckinScore()}%</strong></div>`}
function recoveryCheckinModal(){const c=latestRecoveryCheckin()||{sleep:3,energy:3,soreness:3};modal(`<span class="eyebrow">CHECK-IN DE RECUPERAÇÃO</span><h2>Como você está hoje?</h2><p class="muted small">Este registro complementa a estimativa dos treinos. Ele não substitui avaliação profissional.</p><label>Sono da última noite</label><select id="rcSleep"><option value="1" ${c.sleep==1?'selected':''}>Muito ruim</option><option value="2" ${c.sleep==2?'selected':''}>Ruim</option><option value="3" ${c.sleep==3?'selected':''}>Regular</option><option value="4" ${c.sleep==4?'selected':''}>Bom</option><option value="5" ${c.sleep==5?'selected':''}>Ótimo</option></select><label>Energia hoje</label><select id="rcEnergy"><option value="1" ${c.energy==1?'selected':''}>Muito baixa</option><option value="2" ${c.energy==2?'selected':''}>Baixa</option><option value="3" ${c.energy==3?'selected':''}>Regular</option><option value="4" ${c.energy==4?'selected':''}>Boa</option><option value="5" ${c.energy==5?'selected':''}>Alta</option></select><label>Cansaço muscular geral</label><select id="rcSoreness"><option value="1" ${c.soreness==1?'selected':''}>Nenhum</option><option value="2" ${c.soreness==2?'selected':''}>Leve</option><option value="3" ${c.soreness==3?'selected':''}>Moderado</option><option value="4" ${c.soreness==4?'selected':''}>Alto</option><option value="5" ${c.soreness==5?'selected':''}>Muito alto</option></select><button class="btn primary block" style="margin-top:14px" onclick="saveRecoveryCheckin()">Salvar check-in</button>`)}
function saveRecoveryCheckin(){const item={date:today(),savedAt:new Date().toISOString(),sleep:+$('#rcSleep').value,energy:+$('#rcEnergy').value,soreness:+$('#rcSoreness').value};state.recoveryCheckins=(state.recoveryCheckins||[]).filter(x=>x.date!==item.date);state.recoveryCheckins.push(item);saveLocal();closeModal();renderApp();toast('Check-in de recuperação salvo.')}
function recoveryData(){const now=Date.now();return Object.entries(GROUP_LABELS).map(([id,label])=>{let fatigue=0,lastDate=null,recentSets=0,recentSessions=0;for(const s of state.sessions||[]){const ageH=Math.max(0,(now-new Date(s.date+'T12:00:00').getTime())/3600000);if(ageH>144)continue;let sets=0,rirValues=[];(s.exercises||[]).forEach(ex=>{if(!(EX_GROUPS[ex.id]||[]).includes(id))return;(ex.sets||[]).filter(a=>a.done).forEach(a=>{sets++;const r=+a.rir;if(Number.isFinite(r))rirValues.push(r)})});if(!sets)continue;recentSets+=sets;recentSessions++;if(!lastDate||s.date>lastDate)lastDate=s.date;const rpe=clamp(+s.rpe||7,5,10),rpeFactor=.78+(rpe-5)*.1,avgRir=rirValues.length?rirValues.reduce((a,b)=>a+b,0)/rirValues.length:2,rirFactor=avgRir<=1?1.18:avgRir>=3?.86:1,painFactor=1+Math.min(+s.painAfter||0,6)*.025,decay=Math.exp(-ageH/55);fatigue+=sets*5*rpeFactor*rirFactor*painFactor*decay}fatigue=Math.round(clamp(fatigue,0,100));if(!lastDate)return {id,label,status:'Sem dados',cls:'',detail:'Ainda sem treino registrado',recommendation:'Conclua um treino para iniciar a estimativa.',days:null,fatigue:0,recentSets:0,recentSessions:0};const daysAgo=Math.max(0,Math.floor((new Date(today()+'T12:00:00')-new Date(lastDate+'T12:00:00'))/86400000));let status='Pronta',cls='good',recommendation='Boa prontidão estimada. Faça o aquecimento e reavalie a sensação durante as primeiras séries.';if(fatigue>=75){status='Muito carregada';cls='bad';recommendation='Evite repetir um treino pesado deste grupo hoje. Priorize recuperação ou outra região.'}else if(fatigue>=55){status='Fadiga alta';cls='bad';recommendation='Prefira outro grupo muscular ou reduza claramente carga e volume.'}else if(fatigue>=35){status='Recuperando';cls='warn';recommendation='Um treino leve ou moderado pode ser considerado somente se a execução e a sensação estiverem boas.'}else if(fatigue>=18){status='Fadiga leve';cls='warn';recommendation='Está próxima da recuperação. Aqueça, observe o desempenho e evite forçar se houver queda importante.'}const when=daysAgo===0?'hoje':daysAgo===1?'ontem':`há ${daysAgo} dias`;return {id,label,status,cls,detail:`${recentSets} séries nos últimos 6 dias · último estímulo ${when}`,recommendation,days:daysAgo,fatigue,recentSets,recentSessions}})}
function overallRecoveryScore(){const a=recoveryData().filter(x=>x.days!==null),check=recoveryCheckinScore();if(!a.length)return check??0;const muscular=Math.round(a.reduce((s,x)=>s+(100-x.fatigue),0)/a.length);return check===null?muscular:Math.round(muscular*.8+check*.2)}
function overallRecoveryLabel(){const n=overallRecoveryScore();return n>=82?'Pronta':n>=68?'Boa':n>=48?'Moderada':'Baixa'}
function recoveryBlock(limit=8,detailed=false){const arr=recoveryData().filter(x=>x.days!==null).sort((a,b)=>b.fatigue-a.fatigue).slice(0,limit);if(!arr.length)return '<p class="muted small">Conclua seus primeiros treinos para acompanhar a fadiga por grupo muscular.</p>';return `<div class="recovery-grid recovery-grid-v2">${arr.map(x=>`<div class="recovery-item recovery-item-v2"><div class="row between"><b>${x.label}</b><span class="pill ${x.cls}">${x.status}</span></div><div class="fatigue-bar"><span class="${x.cls}" style="width:${x.fatigue}%"></span></div><div class="recovery-meta"><span>Fadiga estimada: <b>${x.fatigue}%</b></span><span>${x.detail}</span></div>${detailed?`<p>${x.recommendation}</p>`:''}</div>`).join('')}</div><div class="recovery-method"><b>Como a estimativa é calculada</b><span>Tempo desde cada treino, quantidade de séries concluídas, esforço geral da sessão, RIR informado e check-in de sono, energia e cansaço. É uma orientação de organização, não uma medição fisiológica.</span></div>`}
function viewPlanDay(id){const d=state.plan.days.find(x=>x.id===id);modal(`<span class="eyebrow">SEU PLANO</span><h2>${d.name}</h2>${d.exercises.map(x=>exercisePreview(x)).join('')}<div class="grid grid2"><button class="btn secondary block" onclick="openPlanEditor('${d.id}')">Editar exercícios</button><button class="btn primary block" onclick="closeModal();startWorkout('${d.id}')">Iniciar este treino</button></div>`)}
function exercisePreview(x){const e=EX[x.id];return `<div class="card flat">${exerciseMedia(x.id,e)}<div class="row between"><div><h3>${e.name}</h3><span class="muted small">${x.sets} séries · ${x.reps} reps · ${x.rest}s</span></div><span class="pill">${e.machine}</span></div><p class="why">${x.reason}</p><button class="btn ghost sm" onclick="exerciseDetail('${x.id}')">Como executar</button></div>`}


function cardioIcon(id){const paths={treadmill:'M3 17h18M7 14h10l2 3H5zM9 6h6v5H9z',curved_treadmill:'M3 18c5-5 13-5 18 0M6 15h12M10 6h4v6h-4z',elliptical:'M5 18c3-7 11-7 14 0M8 8l4 4 4-7M6 5h4M17 4v7',bike_h:'M4 17h5l3-6h6M8 17a3 3 0 1 1-6 0 3 3 0 0 1 6 0Zm14 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM10 8h5',bike_v:'M4 17a3 3 0 1 1-6 0M22 17a3 3 0 1 1-6 0M7 17l4-7h6l2 7M12 10 9 6h5',walk:'M12 4a2 2 0 1 0 0-4 2 2 0 0 0 0 4Zm-2 4 4 2 2 5M10 8l-2 5-4 4M12 14l-1 7M16 15l3 5',stair:'M4 20h16M6 17h4v-4h4V9h4V5h2M8 8h4M10 5v6',rower:'M3 18h18M6 15h12M8 8l5 5M13 13l5-7M9 5h4',jump_rope:'M6 6c-4 4-4 10 0 14M18 6c4 4 4 10 0 14M9 5h6M10 10l2 3 2-3'};return `<svg class="cardio-icon" viewBox="0 0 24 24"><path d="${paths[id]||paths.walk}"/></svg>`}
function chooseCardio(id){if(!state.active||!CARDIO[id])return;state.active.cardioType=id;state.active.cardioOptions=Object.keys(CARDIO);saveLocal();renderApp();toast(`${cardioName(id)} selecionado.`)}
function cardioPicker(){return `<div class="card cardio-picker"><div class="row between"><div><span class="eyebrow">CARDIO DE HOJE</span><h3 style="margin-top:6px">Você escolhe o aparelho</h3></div><span class="pill good">${state.active.cardio} min</span></div><p class="muted small">A sugestão não é obrigatória. Selecione o aparelho disponível e mais confortável hoje.</p><div class="cardio-grid">${Object.entries(CARDIO).map(([id,c])=>`<button class="cardio-option ${state.active.cardioType===id?'selected':''}" onclick="chooseCardio('${id}')">${cardioIcon(id)}<b>${c.name}</b><span>${c.desc}</span></button>`).join('')}</div></div>`}

function cardioFields(){const f=state.active?.finishDraft||{},id=$('#finishCardioType')?.value||f.cardioType||state.active?.cardioType||'bike_h';let h='<label>Tempo realizado (min)</label><input id="finishCardio" type="number" min="0" value="'+(f.cardio??state.active?.cardio??0)+'" oninput="saveFinishField(\'cardio\',this.value)">';if(id==='treadmill'||id==='curved_treadmill')h+='<div class="grid grid2"><div><label>Velocidade média (km/h)</label><input id="cardioSpeed" type="number" step="0.1" value="'+(f.speed||'')+'" oninput="saveFinishField(\'speed\',this.value)"></div><div><label>Inclinação (%)</label><input id="cardioIncline" type="number" step="0.5" value="'+(f.incline||'')+'" oninput="saveFinishField(\'incline\',this.value)"></div></div>';else if(id==='elliptical'||id==='bike_h'||id==='bike_v'||id==='rower')h+='<div class="grid grid2"><div><label>Nível / resistência</label><input id="cardioLevel" type="number" value="'+(f.level||'')+'" oninput="saveFinishField(\'level\',this.value)"></div><div><label>Distância (km)</label><input id="cardioDistance" type="number" step="0.1" value="'+(f.distance||'')+'" oninput="saveFinishField(\'distance\',this.value)"></div></div>';else if(id==='stair')h+='<div class="grid grid2"><div><label>Nível</label><input id="cardioLevel" type="number" min="0" value="'+(f.level||'')+'" oninput="saveFinishField(\'level\',this.value)"></div><div><label>Andares / lances</label><input id="cardioFloors" type="number" min="0" value="'+(f.floors||'')+'" oninput="saveFinishField(\'floors\',this.value)"></div></div>';else if(id==='jump_rope')h+='<div class="grid grid2"><div><label>Nível de esforço (1–10)</label><input id="cardioLevel" type="number" min="1" max="10" value="'+(f.level||'')+'" oninput="saveFinishField(\'level\',this.value)"></div><div><label>Observação de ritmo</label><input id="cardioPace" value="'+(f.pace||'')+'" placeholder="ex.: intervalado" oninput="saveFinishField(\'pace\',this.value)"></div></div>';else h+='<div class="grid grid2"><div><label>Distância (km)</label><input id="cardioDistance" type="number" step="0.1" value="'+(f.distance||'')+'" oninput="saveFinishField(\'distance\',this.value)"></div><div><label>Ritmo médio (min/km)</label><input id="cardioPace" value="'+(f.pace||'')+'" placeholder="ex.: 12:30" oninput="saveFinishField(\'pace\',this.value)"></div></div>';return h}
function renderCardioFields(){const box=$('#cardioFieldsBox');if(box)box.innerHTML=cardioFields()}
function startWorkout(dayId){const d=state.plan.days.find(x=>x.id===dayId);state.active={id:uid(),dayId,date:today(),startedAt:Date.now(),exercises:d.exercises.map(x=>({id:x.id,sets:Array.from({length:x.sets},()=>({kg:'',reps:'',rir:'',done:false}))})),cardio:d.cardio,cardioType:d.cardioType||'bike_h',cardioOptions:Object.keys(CARDIO),painBefore:0,finishDraft:{cardio:d.cardio||0,cardioType:d.cardioType||'bike_h',speed:'',incline:'',level:'',distance:'',pace:'',floors:'',pain:0,rpe:7,notes:''}};saveLocal();screen='workout';renderApp()}
function workoutScreen(){if(!state.active)return `<section class="hero"><span class="eyebrow">TREINOS</span><h2>Escolha a sessão</h2><p>Seu ciclo foi montado a partir da avaliação inicial e pode ser editado com todas as opções cadastradas.</p></section>${(state.plan?.days||[]).map((d,i)=>`<div class="card"><div class="row between"><div><span class="eyebrow">DIA ${i+1}</span><h3>${d.name}</h3><span class="muted small">${d.exercises.length} exercícios</span></div><div class="row wrap"><button class="btn secondary sm" onclick="openPlanEditor('${d.id}')">Editar</button><button class="btn primary sm" onclick="startWorkout('${d.id}')">Iniciar</button></div></div></div>`).join('')}<div class="card"><h3>${Object.keys(EX).length} exercícios cadastrados</h3><p class="muted small">Eles ficam disponíveis para editar o plano, adicionar durante o treino, trocar aparelhos, usar no Coach e acompanhar nos relatórios.</p></div><div class="card"><h3>Histórico recente</h3>${state.sessions.slice(-4).reverse().map(s=>`<div class="row between" style="padding:10px 0;border-bottom:1px solid var(--line)"><div><b>${s.name}</b><div class="muted small">${fmt(s.date)} · ${s.duration} min · ${s.cardio||0} min ${s.cardioType?`· ${cardioName(s.cardioType)}`:''}</div></div><span class="pill">RPE ${s.rpe||'—'}</span></div>`).join('')||'<p class="muted">Nenhum treino concluído ainda.</p>'}</div>`;const d=(state.plan?.days||[]).find(x=>x.id===state.active.dayId);if(!d){state.active=null;saveLocal();return `<section class="hero"><span class="eyebrow">TREINOS</span><h2>Treino em andamento restaurado</h2><p>O treino salvo anteriormente não era mais compatível com o plano atual. Ele foi encerrado com segurança para liberar o acesso ao app.</p></section><div class="card"><button class="btn primary block" onclick="setScreen('workout')">Continuar</button></div>`;}const done=state.active.exercises.filter(x=>x.sets.every(s=>s.done)).length;return `<section class="hero"><span class="eyebrow">TREINO EM ANDAMENTO</span><h2>${d.name}</h2><p>${done} de ${state.active.exercises.length} exercícios concluídos.</p><p class="small" style="margin-top:8px;opacity:.82">✓ Salvamento automático ativo</p></section>${state.active.exercises.map((x,i)=>activeExercise(x,i)).join('')}<div class="card"><button class="btn secondary block" onclick="openActiveExercisePicker()">${icon('plus')} Adicionar outro exercício</button><p class="muted small" style="margin-top:8px">A busca é somente por texto; a imagem aparece depois de adicionar.</p></div><div class="card"><h3>Finalização</h3><label>Qual cardio você fez?</label><select id="finishCardioType" onchange="chooseFinishCardio(this.value)">${Object.keys(CARDIO).map(id=>`<option value="${id}" ${id===state.active.cardioType?'selected':''}>${cardioName(id)}</option>`).join('')}</select><p class="muted small">Escolha livremente o aparelho usado hoje.</p><div id="cardioFieldsBox">${cardioFields()}</div><label>Dor no joelho após o treino: <b id="painVal">${state.active.finishDraft?.pain||0}/10</b></label><input id="finishPain" type="range" min="0" max="10" value="${state.active.finishDraft?.pain||0}" oninput="painVal.textContent=this.value+'/10';saveFinishField('pain',this.value)"><label>Esforço geral</label><select id="finishRpe" onchange="saveFinishField('rpe',this.value)">${[5,6,7,8,9].map(v=>`<option value="${v}" ${String(state.active.finishDraft?.rpe||7)===String(v)?'selected':''}>${v} — ${v===5?'leve':v===6?'moderado':v===7?'desafiador e controlado':v===8?'difícil':'muito difícil'}</option>`).join('')}</select><label>Observações</label><textarea id="finishNotes" placeholder="Dor, máquina ocupada, execução, energia, fadiga..." oninput="saveFinishField('notes',this.value)">${state.active.finishDraft?.notes||''}</textarea><button class="btn primary block" style="margin-top:13px" onclick="finishWorkout()">${icon('check')} Concluir treino</button><button class="btn danger block" style="margin-top:8px" onclick="cancelWorkout()">Cancelar sessão</button></div>${restSeconds>0?`<div class="restbar"><div><span class="eyebrow">DESCANSO</span><div class="timer" id="restDisplay">${timeText(restSeconds)}</div></div><button class="btn secondary sm" onclick="stopRest()">Pular</button></div>`:''}`}
function activeExercise(x,ei){const e=EX[x.id],complete=x.sets.every(s=>s.done);return `<div class="card workout-card">${exerciseMedia(x.id,e)}<div class="exercise-row"><div><div class="row wrap"><span class="pill">${e.machine}</span><span class="pill ${complete?'good':''}">${complete?'concluído':e.pattern}</span></div><h3 style="margin-top:9px">${e.name}</h3><p class="why">${e.why}</p></div><button class="btn secondary sm" onclick="exerciseDetail('${x.id}')">${icon('info')}</button></div><div class="row wrap"><button class="btn ghost sm" onclick="replacement('${x.id}',${ei})">Trocar exercício</button><button class="btn ghost sm" onclick="startRest(${e.rest})">${icon('clock')} ${e.rest}s</button><button class="btn danger sm" onclick="removeActiveExercise(${ei})">Remover</button></div><div class="set-head"><span>#</span><span>kg</span><span>reps</span><span>RIR</span><span></span></div>${x.sets.map((s,si)=>`<div class="set-row"><b>${si+1}</b><input inputmode="decimal" value="${s.kg}" placeholder="kg" oninput="setValue(${ei},${si},'kg',this.value)"><input inputmode="numeric" value="${s.reps}" placeholder="reps" oninput="setValue(${ei},${si},'reps',this.value)"><input inputmode="numeric" value="${s.rir}" placeholder="2" oninput="setValue(${ei},${si},'rir',this.value)"><button class="set-check ${s.done?'done':''}" onclick="toggleSet(${ei},${si},${e.rest})">${s.done?icon('check'):'○'}</button></div>`).join('')}</div>`}
function setValue(ei,si,k,v){state.active.exercises[ei].sets[si][k]=v;saveLocal()}
function toggleSet(ei,si,rest){const s=state.active.exercises[ei].sets[si];s.done=!s.done;saveLocal();if(s.done)startRest(rest);renderApp()}
function startRest(sec){stopRest();restSeconds=sec;restTimer=setInterval(()=>{restSeconds--;const d=$('#restDisplay');if(d)d.textContent=timeText(restSeconds);if(restSeconds<=0){stopRest();toast('Descanso concluído.')}},1000);renderApp()}
function stopRest(){clearInterval(restTimer);restTimer=null;restSeconds=0;renderApp()}
function timeText(n){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function finishWorkout(){persistActiveFromDOM(false);const a=state.active,d=(state.plan?.days||[]).find(x=>x.id===a?.dayId),f=a?.finishDraft||{},pain=+f.pain||0;if(!a||!d){state.active=null;saveLocal();stopRest();screen='workout';renderApp();toast('O treino salvo estava inconsistente e foi encerrado com segurança.');return}state.sessions.push({id:a.id,date:a.date,name:d.name,dayId:d.id,duration:Math.max(1,Math.round((Date.now()-a.startedAt)/60000)),cardio:+f.cardio||0,cardioType:f.cardioType||a.cardioType||'bike_h',cardioDetails:{speed:+f.speed||0,incline:+f.incline||0,level:+f.level||0,distance:+f.distance||0,pace:f.pace||'',floors:+f.floors||0},painAfter:pain,rpe:+f.rpe||7,notes:f.notes||'',exercises:a.exercises});state.pain.push({date:a.date,value:pain});state.active=null;saveLocal();stopRest();screen='reports';renderApp();toast('Treino salvo e sincronizado.')}
function cancelWorkout(){if(confirm('Cancelar o treino em andamento?')){state.active=null;saveLocal();renderApp()}}

function exerciseDetail(id){const e=EX[id],src=EVIDENCE[e.source];modal(`<span class="eyebrow">COMO EXECUTAR</span><h2>${e.name}</h2>${exerciseMedia(id,e,'detail-media')}<div class="grid grid2"><div class="metric"><b>${e.machine}</b><span>aparelho</span></div><div class="metric"><b>${e.reps}</b><span>faixa sugerida</span></div></div><h3>Execução</h3><ol>${e.cues.map(c=>`<li>${c}</li>`).join('')}</ol><div class="notice"><b>Interrompa e reavalie se:</b><br>${e.avoid.join(' · ')}</div><div class="source"><b>${src.title}</b><p>${src.note}</p></div><p class="muted small">Quando existe uma ilustração, ela é anatômica e corresponde ao exercício mostrado. Exercícios ainda sem imagem permanecem sem foto para evitar demonstrações incorretas. O modelo da máquina pode variar; peça ao professor para regular banco, eixo e amplitude.</p>`)}
function compatible(a,b){let score=0;if(a.pattern===b.pattern)score+=55;score+=a.primary.filter(x=>b.primary.includes(x)).length*18;if(b.knee==='ok'||b.knee==='adapt')score+=5;if(b.back==='ok'||b.back==='adapt')score+=5;return clamp(score,0,100)}
function blocked(e){const l=state.profile.limitations||[];return (l.includes('knee')&&e.knee==='avoid')||(l.includes('back')&&e.back==='avoid')||(l.includes('shoulder')&&e.shoulder==='avoid')}
function getSubs(id){const a=EX[id],preferred=new Set(a.subs||[]);return Object.entries(EX).filter(([k,e])=>k!==id&&!blocked(e)).map(([id,e])=>({id,e,score:clamp(compatible(a,e)+(preferred.has(id)?18:0),0,100)})).filter(x=>x.score>=45).sort((x,y)=>y.score-x.score).slice(0,5)}
function replacement(id,index=null){const e=EX[id],subs=getSubs(id);modal(`<span class="eyebrow">SUBSTITUIÇÃO ANALISADA</span><h2>Trocar ${e.name}</h2><p class="muted">As primeiras opções são ranqueadas por padrão de movimento e musculatura.</p>${subs.length?subs.map(s=>`<div class="card flat"><div class="row between"><div><h3>${s.e.name}</h3><span class="muted small">${s.e.machine} · ${s.e.pattern}</span></div><b>${s.score}%</b></div><div class="score" style="margin:10px 0"><span style="width:${s.score}%"></span></div>${index!==null?`<button class="btn primary sm" onclick="applyReplacement(${index},'${s.id}')">Usar no treino</button>`:''}</div>`).join(''):`<div class="notice">Não há alternativa suficientemente equivalente na base.</div>`}${index!==null?`<button class="btn secondary block" onclick="openManualReplacement(${index})">Ver todas as opções cadastradas</button>`:''}<div class="source"><b>Regra de segurança</b><p>Recuse a troca se houver dor, técnica insegura ou movimento não familiar.</p></div>`)}
function applyReplacement(i,id){state.active.exercises[i]={id,sets:Array.from({length:EX[id].sets},()=>({kg:'',reps:'',rir:'',done:false}))};saveLocal();closeModal();renderApp();toast('Substituição aplicada.')}

function coachScreen(){return `<section class="hero"><span class="eyebrow">COACH INTELIGENTE</span><h2>Decisão explicada, não improvisada.</h2><p>O modo offline usa regras da base de exercícios. A IA generativa pode ser conectada no backend sem expor a chave no aplicativo.</p></section><div class="card"><label>Exercício atual</label><select id="coachEx">${Object.entries(EX).map(([id,e])=>`<option value="${id}">${e.name}</option>`).join('')}</select><label>O que aconteceu?</label><select id="coachIntent"><option value="occupied">A máquina está ocupada</option><option value="load">Quero saber se aumento a carga</option><option value="pain">Senti dor durante o exercício</option><option value="technique">Quero revisar a execução</option></select><label>Dor agora (0–10)</label><input id="coachPain" type="range" min="0" max="10" value="0"><label>Pergunta adicional</label><textarea id="coachQuestion" placeholder="Ex.: só tenho leg press horizontal disponível"></textarea><button class="btn primary block" style="margin-top:13px" onclick="coachAnswer()">${icon('coach')} Analisar</button></div><div id="coachResult"></div><div class="card"><h3>Limites do Coach</h3><p class="muted small">Não diagnostica, não prescreve tratamento e não substitui avaliação presencial. Em dor forte, inchaço, travamento, sintomas cardiopulmonares ou piora progressiva, a resposta correta é interromper e buscar avaliação.</p></div>`}
async function coachAnswer(){const id=$('#coachEx').value,intent=$('#coachIntent').value,pain=+$('#coachPain').value,q=$('#coachQuestion').value,e=EX[id],box=$('#coachResult');box.innerHTML='<div class="card"><p class="muted">Analisando contexto…</p></div>';if(pain>=5||intent==='pain'&&pain>=4){box.innerHTML=`<div class="assistant-msg ai"><b>Interrompa este exercício agora.</b><p>Dor moderada/forte não deve ser “compensada” com outra máquina sem avaliação. Reduza a atividade e procure o professor; sinais como inchaço, travamento ou dor persistente exigem avaliação de saúde.</p></div>`;return}if(C.aiFunctionUrl&&cloud&&currentUser&&q.trim()){try{const {data:{session}}=await cloud.auth.getSession();const r=await fetch(C.aiFunctionUrl,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${session.access_token}`},body:JSON.stringify({question:q,exercise:e,profile:state.profile,recentSessions:state.sessions.slice(-5)})});if(r.ok){const d=await r.json();box.innerHTML=`<div class="assistant-msg ai">${d.answer}</div>`;return}}catch(err){console.warn(err)}}let html='';if(intent==='occupied'){const subs=getSubs(id);html=`<div class="assistant-msg ai"><b>Melhor opção cadastrada: ${subs[0]?.e.name||'nenhuma'}</b><p>${subs[0]?`Compatibilidade ${subs[0].score}%. ${subs[0].e.pattern===e.pattern?'Mantém o padrão principal de movimento.':'O estímulo é relacionado, mas não idêntico.'}`:'A base de exercícios não encontrou equivalência segura.'}</p><button class="btn ghost sm" onclick="replacement('${id}')">Ver alternativas</button></div>`}else if(intent==='load'){const hist=exerciseHistory(id);const ok=hist.length>=2&&hist.slice(-2).every(h=>h.avgRir>=2&&h.pain<3&&h.completed);html=`<div class="assistant-msg ai"><b>${ok?'Progressão mínima pode ser considerada.':'Ainda não recomendo aumentar.'}</b><p>${ok?'Você completou as duas últimas exposições com margem de repetições, baixa dor e séries completas. Aumente apenas o menor incremento da máquina e reavalie técnica e dor.':'Precisamos de pelo menos duas sessões estáveis: topo da faixa de repetições, RIR em torno de 2–3, sem piora de dor e execução consistente.'}</p></div>`}else if(intent==='technique'){html=`<div class="assistant-msg ai"><b>${e.name}</b><ol>${e.cues.map(x=>`<li>${x}</li>`).join('')}</ol></div>`}else html=`<div class="assistant-msg ai"><b>Não force a repetição.</b><p>Reduza carga e amplitude. Se a dor voltar ou persistir, interrompa o exercício e peça avaliação.</p></div>`;box.innerHTML=html}
function exerciseHistory(id){return (state.sessions||[]).map(s=>{const x=(s.exercises||[]).find(e=>e.id===id);if(!x)return null;const sets=Array.isArray(x.sets)?x.sets:[],done=sets.filter(a=>a&&a.done),rirs=done.map(a=>+a.rir).filter(Number.isFinite);return {completed:sets.length>0&&done.length===sets.length,avgRir:rirs.length?rirs.reduce((a,b)=>a+b,0)/rirs.length:0}}).filter(Boolean)}

function cardioSummaryBlock(){
 const totals={};
 for(const s of (state.sessions||[])){
  const id=CARDIO[s?.cardioType]?s.cardioType:'other';
  const minutes=Math.max(0,+s?.cardio||0);
  if(!minutes)continue;
  totals[id]=(totals[id]||0)+minutes;
 }
 const rows=Object.entries(totals).sort((a,b)=>b[1]-a[1]);
 if(!rows.length)return '<p class="muted">Nenhum cardio registrado ainda.</p>';
 const max=Math.max(...rows.map(x=>x[1]),1);
 return `<div class="cardio-summary">${rows.map(([id,min])=>`<div class="cardio-summary-row"><div class="row between"><b>${id==='other'?'Outro cardio':cardioName(id)}</b><span>${Math.round(min)} min</span></div><div class="progress"><span style="width:${Math.max(4,min/max*100)}%"></span></div></div>`).join('')}</div>`;
}

function reportsScreen(){
 const sessions=Array.isArray(state.sessions)?state.sessions:[],mins=sessions.reduce((a,x)=>a+(+x?.duration||0),0),cardio=sessions.reduce((a,x)=>a+(+x?.cardio||0),0),metrics=(Array.isArray(state.metrics)?state.metrics:[]).slice(-10),lastMetric=metrics.length?metrics[metrics.length-1]:null,readiness=overallRecoveryScore();
 return `<section class="hero"><span class="eyebrow">RELATÓRIOS</span><h2>Progresso de fácil leitura.</h2><p>Treino, peso, volume, aderência, cardio e recuperação no mesmo painel.</p></section><div class="card report-export-card"><div class="row between report-export-row"><div><span class="eyebrow">RELATÓRIO COMPLETO</span><h3 style="margin-top:5px">Gerar relatório em PDF</h3><p class="muted small">Abre uma versão organizada para salvar como PDF ou imprimir.</p></div><div class="report-export-actions"><select id="pdfPeriod" aria-label="Período do relatório"><option value="30">Últimos 30 dias</option><option value="90" selected>Últimos 90 dias</option><option value="180">Últimos 6 meses</option><option value="all">Todo o histórico</option></select><button class="btn primary" onclick="generateProgressPdf()">${icon('chart')} Gerar PDF</button></div></div></div><div class="grid grid3 premium-metrics" style="margin-top:12px"><div class="metric"><b>${sessions.length}</b><span>treinos concluídos</span></div><div class="metric"><b>${mins}</b><span>min de força</span></div><div class="metric"><b>${cardio}</b><span>min de cardio</span></div></div><div class="card premium-insight"><span class="eyebrow">RESUMO PREMIUM</span><div class="grid grid3" style="margin-top:10px"><div><b>${readiness}%</b><span>prontidão geral</span></div><div><b>${Math.round(sessions.length/Math.max(1,+state.profile?.days||1)*100)}%</b><span>aderência acumulada</span></div><div><b>${lastMetric?.weight||state.profile?.weight||'—'} kg</b><span>peso mais recente</span></div></div></div><div class="card premium-recovery"><div class="row between"><div><h3>Fadiga e recuperação muscular</h3><span class="muted small">Grupos com maior fadiga aparecem primeiro.</span></div><div class="recovery-ring small-ring" style="--score:${readiness*3.6}deg"><div><b>${readiness}%</b><span>${overallRecoveryLabel()}</span></div></div></div>${recoveryCheckinSummary()}<button class="btn secondary block" style="margin:10px 0 12px" onclick="recoveryCheckinModal()">Atualizar check-in</button>${recoveryBlock(8,true)}</div><div class="card"><div class="row between"><div><h3>Peso</h3><span class="muted small">Últimos registros</span></div><button class="btn secondary sm" onclick="metricModal()">${icon('plus')} Registrar</button></div>${weightChart(metrics)}</div><div class="card"><h3>Volume por sessão</h3>${volumeChart(sessions.slice(-8))}</div><div class="card"><h3>Cardio por aparelho</h3>${cardioSummaryBlock()}</div><div class="card"><h3>Evolução por exercício</h3><select id="reportEx" onchange="renderExerciseReport(this.value)">${Object.entries(EX).map(([id,e])=>`<option value="${id}">${e.name}</option>`).join('')}</select><div id="exerciseReport">${exerciseReportHtml('legpressh')}</div></div><div class="card"><h3>Histórico</h3>${sessions.slice().reverse().map(x=>`<div class="row between" style="padding:11px 0;border-bottom:1px solid var(--line)"><div><b>${x.name}</b><div class="muted small">${fmt(x.date)} · ${x.duration} min · cardio ${x.cardio} min${x.cardioType?` · ${cardioName(x.cardioType)}`:''}</div></div><button class="btn secondary sm" onclick="sessionDetail('${x.id}')">Ver</button></div>`).join('')||'<p class="muted">Seu relatório aparece após o primeiro treino.</p>'}</div>`;
}
function weightChart(a){if(!a.length)return '<p class="muted">Sem dados.</p>';const vals=a.map(x=>+x.weight),min=Math.min(...vals)-1,max=Math.max(...vals)+1;return `<div class="chart">${a.map(x=>`<div class="chartbar" style="height:${35+(x.weight-min)/(max-min||1)*120}px"><b>${x.weight}</b><small>${fmt(x.date)}</small></div>`).join('')}</div>`}
function sessionVolume(s){return (s?.exercises||[]).reduce((sum,e)=>sum+(e?.sets||[]).reduce((a,x)=>a+(x?.done?(+x.kg||0)*(+x.reps||0):0),0),0)}
function volumeChart(a){if(!a.length)return '<p class="muted">Sem dados.</p>';const vals=a.map(sessionVolume),max=Math.max(...vals,1);return `<div class="chart">${a.map((x,i)=>`<div class="chartbar" style="height:${25+vals[i]/max*135}px"><b>${Math.round(vals[i])}</b><small>${fmt(x.date)}</small></div>`).join('')}</div><p class="muted small">Volume = carga × repetições das séries registradas. Serve para acompanhar tendência, não para comparar exercícios diferentes.</p>`}
function painChart(a){if(!a.length)return '<p class="muted">Sem dados.</p>';return `<svg class="linechart" viewBox="0 0 640 210"><path d="M35 175H610M35 25V175" stroke="#384145" fill="none"/>${a.map((x,i)=>{const px=45+i*(550/Math.max(1,a.length-1)),py=175-(+x.value||0)*14;return `${i?`<line x1="${45+(i-1)*(550/Math.max(1,a.length-1))}" y1="${175-(+a[i-1].value||0)*14}" x2="${px}" y2="${py}" stroke="#d5a277" stroke-width="4"/>`:''}<circle cx="${px}" cy="${py}" r="7" fill="#f0d2bd"/><text x="${px}" y="200" text-anchor="middle" fill="#9ba4a7" font-size="11">${fmt(x.date)}</text>`}).join('')}</svg>`}
function exerciseReportHtml(id){const h=exerciseHistory(id);if(!h.length)return '<p class="muted">Ainda não há registros deste exercício.</p>';return `<div class="grid grid2" style="margin-top:11px"><div class="metric"><b>${h.length}</b><span>sessões registradas</span></div><div class="metric"><b>${h.at(-1).avgRir.toFixed(1)}</b><span>RIR médio recente</span></div></div><p class="muted small">${h.length>=2&&h.slice(-2).every(x=>x.completed&&x.avgRir>=2)?'Tendência estável: progressão mínima pode ser avaliada.':'Mantenha a carga até consolidar execução, repetições e regularidade.'}</p>`}
function renderExerciseReport(id){$('#exerciseReport').innerHTML=exerciseReportHtml(id)}
function metricModal(){modal(`<span class="eyebrow">NOVO REGISTRO</span><h2>Peso e medidas</h2><label>Data</label><input id="mDate" type="date" value="${today()}"><label>Peso (kg)</label><input id="mWeight" type="number" step=".1"><div class="grid grid2"><div><label>Cintura (cm)</label><input id="mWaist" type="number" step=".1"></div><div><label>Abdômen (cm)</label><input id="mAbd" type="number" step=".1"></div><div><label>Quadril (cm)</label><input id="mHip" type="number" step=".1"></div><div><label>Coxa (cm)</label><input id="mThigh" type="number" step=".1"></div></div><button class="btn primary block" style="margin-top:14px" onclick="saveMetric()">Salvar registro</button>`)}
function saveMetric(){const weight=+$('#mWeight').value;if(!weight)return toast('Informe o peso.');state.metrics.push({date:$('#mDate').value,weight,waist:+$('#mWaist').value||null,abd:+$('#mAbd').value||null,hip:+$('#mHip').value||null,thigh:+$('#mThigh').value||null});state.metrics.sort((a,b)=>a.date.localeCompare(b.date));saveLocal();closeModal();renderApp();toast('Métrica salva.')}
function sessionDetail(id){const s=state.sessions.find(x=>x.id===id);modal(`<span class="eyebrow">SESSÃO CONCLUÍDA</span><h2>${s.name}</h2><p class="muted">${fmt(s.date)} · ${s.duration} min · RPE ${s.rpe||'—'}</p>${s.exercises.map(x=>`<div class="card flat"><h3>${EX[x.id]?.name||'Exercício removido'}</h3><p class="muted small">${x.sets.map((a,i)=>`${i+1}: ${a.kg||'—'} kg × ${a.reps||'—'} · RIR ${a.rir||'—'}`).join('<br>')}</p></div>`).join('')}<p><b>Observações:</b> ${s.notes||'Nenhuma'}</p>`)}

function reportEscape(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function reportDate(value){if(!value)return '—';const d=new Date(String(value).slice(0,10)+'T12:00:00');return Number.isNaN(d.getTime())?'—':d.toLocaleDateString('pt-BR')}
function reportPeriodData(period){
 const allSessions=(Array.isArray(state.sessions)?state.sessions:[]).slice().sort((a,b)=>String(a.date).localeCompare(String(b.date))),allMetrics=(Array.isArray(state.metrics)?state.metrics:[]).slice().sort((a,b)=>String(a.date).localeCompare(String(b.date)));
 if(period==='all')return {sessions:allSessions,metrics:allMetrics,start:null};
 const days=Math.max(1,+period||90),start=new Date();start.setHours(0,0,0,0);start.setDate(start.getDate()-days+1);const iso=start.toISOString().slice(0,10);
 return {sessions:allSessions.filter(x=>x.date>=iso),metrics:allMetrics.filter(x=>x.date>=iso),start:iso};
}
function reportExerciseProgress(sessions){
 const map={};
 sessions.forEach(session=>(session.exercises||[]).forEach(item=>{
  const done=(item.sets||[]).filter(set=>set.done||(+set.kg>0&&+set.reps>0));if(!done.length)return;
  const maxKg=Math.max(...done.map(set=>+set.kg||0)),volume=done.reduce((sum,set)=>sum+(+set.kg||0)*(+set.reps||0),0),row=map[item.id]||{id:item.id,count:0,firstKg:maxKg,lastKg:maxKg,bestKg:maxKg,totalVolume:0};
  row.count++;row.lastKg=maxKg;row.bestKg=Math.max(row.bestKg,maxKg);row.totalVolume+=volume;map[item.id]=row;
 }));
 return Object.values(map).sort((a,b)=>b.count-a.count||((EX[a.id]?.name||'').localeCompare(EX[b.id]?.name||'')));
}
function generateProgressPdf(){
 const period=document.getElementById('pdfPeriod')?.value||'90',data=reportPeriodData(period),sessions=data.sessions,metrics=data.metrics,profile=state.profile||{},readiness=overallRecoveryScore(),strengthMinutes=sessions.reduce((sum,x)=>sum+(+x.duration||0),0),cardioMinutes=sessions.reduce((sum,x)=>sum+(+x.cardio||0),0),firstWeight=metrics.length?(+metrics[0].weight||null):null,lastWeight=metrics.length?(+metrics[metrics.length-1].weight||null):(+profile.weight||null),weightDelta=metrics.length>=2&&firstWeight!==null&&lastWeight!==null?lastWeight-firstWeight:null;
 const dateValues=[...sessions.map(x=>x.date),...metrics.map(x=>x.date)].filter(Boolean).sort(),startLabel=data.start?reportDate(data.start):(dateValues.length?reportDate(dateValues[0]):'início'),endLabel=reportDate(today()),spanDays=data.start?Math.max(1,Math.round((new Date(today()+'T12:00:00')-new Date(data.start+'T12:00:00'))/86400000)+1):Math.max(1,dateValues.length?Math.round((new Date(today()+'T12:00:00')-new Date(dateValues[0]+'T12:00:00'))/86400000)+1:1),expected=Math.max(1,Math.round(spanDays/7*Math.max(1,+profile.days||1))),adherence=Math.min(100,Math.round(sessions.length/expected*100));
 const cardioMap={};sessions.forEach(x=>{if(+x.cardio>0){const id=x.cardioType||'other';cardioMap[id]=(cardioMap[id]||0)+(+x.cardio||0)}});const cardioRows=Object.entries(cardioMap).sort((a,b)=>b[1]-a[1]);
 const exerciseRows=reportExerciseProgress(sessions),recoveryRows=recoveryData().filter(x=>x.days!==null).sort((a,b)=>b.fatigue-a.fatigue),history=sessions.slice(-20).reverse();
 const weightText=lastWeight===null?'—':`${lastWeight.toFixed(1)} kg`,deltaText=weightDelta===null?'Sem comparação':`${weightDelta>0?'+':''}${weightDelta.toFixed(1)} kg`;
 const win=window.open('','_blank');if(!win){toast('O navegador bloqueou a abertura do relatório. Permita pop-ups e tente novamente.');return;}
 const html=`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Relatório de progresso GYM</title><style>
 @page{size:A4;margin:12mm}*{box-sizing:border-box}body{font-family:Arial,Helvetica,sans-serif;color:#1d1b22;margin:0;background:#fff;font-size:12px;line-height:1.45}.top-actions{position:sticky;top:0;background:#fff;padding:10px 0;border-bottom:1px solid #ddd;margin-bottom:14px}.top-actions button{border:0;border-radius:8px;padding:10px 16px;background:#e84c8b;color:#fff;font-weight:700;cursor:pointer}.head{display:flex;justify-content:space-between;gap:20px;border-bottom:3px solid #e84c8b;padding-bottom:12px;margin-bottom:16px}.brand{font-size:26px;font-weight:900}.brand span{display:block;color:#e84c8b;font-size:11px;letter-spacing:2px}.muted{color:#666}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:12px 0 18px}.metric{border:1px solid #ddd;border-radius:10px;padding:10px}.metric b{display:block;font-size:18px;color:#d53d7b}.section{margin:16px 0;page-break-inside:avoid}.section h2{font-size:16px;margin:0 0 8px;border-left:4px solid #e84c8b;padding-left:8px}table{width:100%;border-collapse:collapse;font-size:11px}th,td{border:1px solid #ddd;padding:7px;text-align:left;vertical-align:top}th{background:#f5edf1}.pill{display:inline-block;border-radius:999px;background:#f4e6ec;padding:3px 7px}.note{background:#f7f7f7;border-radius:8px;padding:10px;margin-top:12px}.footer{margin-top:18px;border-top:1px solid #ddd;padding-top:8px;color:#666;font-size:10px}.empty{color:#777;font-style:italic}.bar{height:7px;background:#eee;border-radius:6px;overflow:hidden;margin-top:4px}.bar span{display:block;height:100%;background:#e84c8b}@media print{.top-actions{display:none}.section{break-inside:avoid}body{font-size:11px}}
 </style></head><body><div class="top-actions"><button onclick="window.print()">Salvar como PDF / Imprimir</button></div><header class="head"><div><div class="brand">GYM<span>RELATÓRIO DE PROGRESSO</span></div><div class="muted">${reportEscape(profile.name||'Atleta')}</div></div><div style="text-align:right"><b>Período</b><br>${startLabel} a ${endLabel}<br><span class="muted">Gerado em ${new Date().toLocaleString('pt-BR')}</span></div></header><div class="grid"><div class="metric"><b>${sessions.length}</b>treinos concluídos</div><div class="metric"><b>${strengthMinutes}</b>min de musculação</div><div class="metric"><b>${cardioMinutes}</b>min de cardio</div><div class="metric"><b>${adherence}%</b>aderência estimada</div><div class="metric"><b>${weightText}</b>peso mais recente</div><div class="metric"><b>${deltaText}</b>variação no período</div><div class="metric"><b>${readiness}%</b>prontidão atual</div><div class="metric"><b>${exerciseRows.length}</b>exercícios registrados</div></div><section class="section"><h2>Evolução de peso e medidas</h2>${metrics.length?`<table><thead><tr><th>Data</th><th>Peso</th><th>Cintura</th><th>Abdômen</th><th>Quadril</th><th>Coxa</th></tr></thead><tbody>${metrics.map(x=>`<tr><td>${reportDate(x.date)}</td><td>${x.weight??'—'} kg</td><td>${x.waist??'—'}</td><td>${x.abd??'—'}</td><td>${x.hip??'—'}</td><td>${x.thigh??'—'}</td></tr>`).join('')}</tbody></table>`:'<p class="empty">Nenhum registro de peso ou medidas neste período.</p>'}</section><section class="section"><h2>Evolução por exercício</h2>${exerciseRows.length?`<table><thead><tr><th>Exercício</th><th>Sessões</th><th>Primeira carga máx.</th><th>Última carga máx.</th><th>Melhor carga</th><th>Volume total</th></tr></thead><tbody>${exerciseRows.slice(0,25).map(x=>`<tr><td>${reportEscape(EX[x.id]?.name||x.id)}</td><td>${x.count}</td><td>${x.firstKg||'—'} kg</td><td>${x.lastKg||'—'} kg</td><td>${x.bestKg||'—'} kg</td><td>${Math.round(x.totalVolume)}</td></tr>`).join('')}</tbody></table>`:'<p class="empty">Ainda não existem séries registradas neste período.</p>'}</section><section class="section"><h2>Cardio por aparelho</h2>${cardioRows.length?`<table><thead><tr><th>Modalidade</th><th>Minutos</th></tr></thead><tbody>${cardioRows.map(([id,min])=>`<tr><td>${reportEscape(id==='other'?'Outro cardio':cardioName(id))}</td><td>${Math.round(min)}</td></tr>`).join('')}</tbody></table>`:'<p class="empty">Nenhum cardio registrado neste período.</p>'}</section><section class="section"><h2>Fadiga e recuperação atual</h2>${recoveryRows.length?`<table><thead><tr><th>Grupo muscular</th><th>Status</th><th>Fadiga estimada</th><th>Orientação</th></tr></thead><tbody>${recoveryRows.map(x=>`<tr><td>${reportEscape(x.label)}</td><td><span class="pill">${reportEscape(x.status)}</span></td><td>${x.fatigue}%<div class="bar"><span style="width:${x.fatigue}%"></span></div></td><td>${reportEscape(x.recommendation)}</td></tr>`).join('')}</tbody></table>`:'<p class="empty">Conclua treinos para calcular a estimativa por grupo muscular.</p>'}<div class="note">A fadiga é uma estimativa organizacional baseada em tempo desde o treino, séries, RPE, RIR e check-in. Não é uma medição clínica.</div></section><section class="section"><h2>Histórico recente</h2>${history.length?`<table><thead><tr><th>Data</th><th>Treino</th><th>Duração</th><th>Cardio</th><th>RPE</th></tr></thead><tbody>${history.map(x=>`<tr><td>${reportDate(x.date)}</td><td>${reportEscape(x.name||'Treino')}</td><td>${+x.duration||0} min</td><td>${+x.cardio||0} min${x.cardioType?` - ${reportEscape(cardioName(x.cardioType))}`:''}</td><td>${x.rpe||'—'}</td></tr>`).join('')}</tbody></table>`:'<p class="empty">Nenhum treino concluído neste período.</p>'}</section><div class="footer">Relatório gerado pelo GYM Premium. Dados informados pela própria usuária e destinados ao acompanhamento pessoal. Não substitui avaliação de profissional de Educação Física ou de saúde.</div></body></html>`;
 win.document.open();win.document.write(html);win.document.close();setTimeout(()=>{try{win.focus();win.print()}catch{}},500);
}

let profileFocusDraft=[],profilePreferenceDraft=null;
function profileScreen(){const p=state.profile||{},focus=focusNames(p.focusAreas);return `<section class="hero"><span class="eyebrow">PERFIL</span><h2>${p.name||'Atleta'}</h2><p>${goalName(p.goal)} · ${p.days||'—'} dias por semana · ${p.preference==='machines'?'aparelhos':'misto'}</p></section><div class="card"><h3>Dados pessoais</h3><label>Nome</label><input id="pName" value="${p.name||''}"><div class="grid grid2"><div><label>Altura (cm)</label><input id="pHeight" type="number" value="${p.height||''}"></div><div><label>Peso-base (kg)</label><input id="pWeight" type="number" step=".1" value="${p.weight||''}"></div></div><label>Limitações registradas</label><input value="${(p.limitations||[]).join(', ')||'Nenhuma'}" disabled><button class="btn primary block" style="margin-top:14px" onclick="saveProfile()">Salvar alterações</button></div><div class="card"><h3>Foco do plano</h3><p class="muted small">Atual: <b>${focus}</b>. Você pode alterar as prioridades e gerar um ciclo mais específico sem apagar o histórico.</p><button class="btn secondary block" onclick="profileFocusModal()">Alterar foco e estilo do treino</button></div><div class="card"><h3>Conta e sincronização</h3>${currentUser?`<div class="success">${icon('cloud')} Sincronização em nuvem ativa para <b>${currentUser.email}</b>.</div><button class="btn ghost block" style="margin-top:10px" onclick="forceSync()">Sincronizar agora</button><button class="btn danger block" style="margin-top:8px" onclick="logout()">${icon('logout')} Sair</button>`:`<div class="notice">Modo local. Os dados não voltarão automaticamente em outro celular até o Supabase ser configurado e você entrar com uma conta.</div><button class="btn ghost block" style="margin-top:10px" onclick="exitDemo()">Configurar login</button>`}</div><div class="card"><h3>Base científica</h3>${(state.plan?.basis||[]).map(k=>{let s=EVIDENCE[k];return s?`<div class="source"><b>${s.title}</b><p>${s.note}</p></div>`:''}).join('')}<p class="muted small">GYM Premium v5.12 · revisão julho/2026. Para disponibilização pública, cada regra e exercício deve passar por revisão formal de profissional de Educação Física.</p></div><div class="card"><h3>Plano</h3><button class="btn secondary block" onclick="regeneratePlan()">Regerar plano com os dados atuais</button><button class="btn ghost block" style="margin-top:8px" onclick="exportBackup()">Exportar backup</button></div>${currentUser?`<div class="card danger-zone"><h3>Excluir conta</h3><p class="muted small">Exclui definitivamente o login e todos os dados de treino vinculados a esta conta. Esta ação não pode ser desfeita.</p><button class="btn danger block" onclick="deleteAccountModal()">Excluir minha conta e meus dados</button></div>`:''}`}
function saveProfile(){state.profile.name=$('#pName').value.trim();state.profile.height=+$('#pHeight').value;state.profile.weight=+$('#pWeight').value;saveLocal();toast('Perfil atualizado.');renderApp()}
function profileFocusModal(){profileFocusDraft=normalizedFocusAreas(profileFocusDraft.length?profileFocusDraft:state.profile?.focusAreas);profilePreferenceDraft=profilePreferenceDraft||state.profile?.preference||'machines';closeModal();modal(`<span class="eyebrow">FOCO DO PLANO</span><h2>Escolha até 3 áreas</h2><p class="muted small">O histórico será preservado. Ao salvar, um novo ciclo será gerado com divisões diferentes e maior volume nas áreas escolhidas.</p><div class="choice-grid">${Object.entries(FOCUS_OPTIONS).map(([id,o])=>`<button class="choice ${profileFocusDraft.includes(id)?'selected':''}" onclick="toggleProfileFocus('${id}')"><b>${o.name}</b><span class="muted small">${o.desc}</span></button>`).join('')}</div><label>Estilo do treino</label><select onchange="profilePreferenceDraft=this.value"><option value="machines" ${profilePreferenceDraft==='machines'?'selected':''}>Principalmente aparelhos</option><option value="mixed" ${profilePreferenceDraft==='mixed'?'selected':''}>Misto — aparelhos e exercícios livres</option></select><p class="muted small">No estilo misto, o plano passa a usar mais barras, halteres, banco, kettlebells e peso corporal.</p><button class="btn primary block" style="margin-top:14px" onclick="saveProfileFocus()">Salvar e gerar novo plano</button>`)}
function toggleProfileFocus(id){profileFocusDraft=toggleFocusList(profileFocusDraft,id);profileFocusModal()}
function saveProfileFocus(){if(state.active)return toast('Conclua ou cancele o treino em andamento antes de gerar outro plano.');state.profile.focusAreas=normalizedFocusAreas(profileFocusDraft);state.profile.preference=profilePreferenceDraft||state.profile.preference||'machines';state.plan=generatePlan(state.profile);saveLocal();profileFocusDraft=[];profilePreferenceDraft=null;closeModal();screen='home';renderApp();toast('Novo plano gerado com foco e estilo atualizados.')}
async function forceSync(){await syncUp();toast('Dados sincronizados.')}
async function logout(){try{if(cloud)await withTimeout(cloud.auth.signOut(),15000)}catch(err){console.warn('Falha ao sair da nuvem',err)}currentUser=null;screen='home';renderRoot()}
function exitDemo(){localStorage.removeItem('emyfit_demo');currentUser=null;renderRoot()}
function regeneratePlan(){if(state.active)return toast('Conclua ou cancele o treino atual antes de gerar outro plano.');if(confirm('Gerar um novo ciclo com base no perfil e nos focos atuais? O histórico será preservado.')){state.plan=generatePlan(state.profile);saveLocal();screen='home';renderApp();toast('Novo ciclo gerado.')}}
function exportBackup(){const a=document.createElement('a'),b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});a.href=URL.createObjectURL(b);a.download='gym-backup.json';a.click();URL.revokeObjectURL(a.href)}
function deleteAccountModal(){modal(`<span class="eyebrow">EXCLUSÃO DEFINITIVA</span><h2>Excluir conta e dados</h2><div class="dangerbox"><b>Esta ação não pode ser desfeita.</b><br>Serão excluídos o login, o plano, os treinos, as cargas, as medidas e os relatórios desta conta.</div><label>Digite EXCLUIR para confirmar</label><input id="deleteAccountConfirm" autocomplete="off" placeholder="EXCLUIR"><div id="deleteAccountStatus" class="dangerbox" hidden style="margin-top:10px"></div><button id="deleteAccountButton" class="btn danger block" style="margin-top:14px" onclick="deleteAccount()">Excluir definitivamente</button>`)}
async function deleteAccount(){if(!cloud||!currentUser)return;const confirmation=($('#deleteAccountConfirm')?.value||'').trim().toUpperCase(),status=$('#deleteAccountStatus'),button=$('#deleteAccountButton');if(confirmation!=='EXCLUIR'){if(status){status.hidden=false;status.textContent='Digite EXCLUIR exatamente como mostrado.'}return}button.disabled=true;button.textContent='Excluindo…';const key=localKey();try{const {data,error}=await withTimeout(cloud.functions.invoke('delete-account',{body:{confirmation}}),25000);if(error)throw error;if(!data?.ok)throw new Error(data?.error||'A exclusão não foi confirmada pelo servidor.');try{await cloud.auth.signOut({scope:'local'})}catch{}localStorage.removeItem(key);localStorage.removeItem('emyfit_demo');currentUser=null;state=blankState();screen='home';closeModal();renderRoot()}catch(error){console.warn('Falha ao excluir conta',error);if(status){status.hidden=false;status.textContent=String(error?.message||'Não foi possível excluir a conta. Verifique se a função delete-account foi publicada no Supabase.')}button.disabled=false;button.textContent='Excluir definitivamente'}}


boot();
